export const UNIT3_SEGMENT_A_ITEMS = [
  {"id": "3.1-basic-01", "course": "csa", "topic": "3.1", "tier": "basic", "lo": "3.1.A.1", "prompt": "In computer science, abstraction is best described as which of the following?", "choices": ["Focusing on the essential details of a problem while hiding irrelevant complexity", "Writing a program that runs as fast as possible regardless of readability", "Copying working code from one program into another without modification", "Testing a program with as many different inputs as possible"], "answer": 0, "explanation": "Abstraction reduces complexity by focusing on the main idea and hiding irrelevant details (3.1.A.1). Running quickly, copying code, and exhaustive testing are all unrelated goals, not the definition of abstraction."},
  {"id": "3.1-basic-02", "course": "csa", "topic": "3.1", "tier": "basic", "lo": "3.1.A.3", "prompt": "A programmer writes the following class.\npublic class Book\n{\n    private String title;\n    private int pageCount;\n}\nWhat term describes title and pageCount collectively?", "choices": ["Methods", "Attributes", "Parameters", "Local variables"], "answer": 1, "explanation": "Variables declared in a class outside any method or constructor, like title and pageCount, are called attributes. Methods are behaviors, not data; parameters and local variables live inside method bodies, not at the class level."},
  {"id": "3.1-basic-03", "course": "csa", "topic": "3.1", "tier": "basic", "lo": "3.1.A.3", "prompt": "Which statement best describes an instance variable?", "choices": ["A variable declared inside a method that exists only while the method runs", "A variable whose value is shared identically by every object of the class", "A variable whose value can be different for each object created from the class", "A variable that must be declared public so other classes can use it"], "answer": 2, "explanation": "An instance variable's value is unique to each object of the class. A value shared by every object describes a class variable instead, and a method-only variable describes a local variable, not an instance variable."},
  {"id": "3.1-basic-04", "course": "csa", "topic": "3.1", "tier": "basic", "lo": "3.1.A.3", "prompt": "A class variable differs from an instance variable in that a class variable's value is...", "choices": ["only usable inside constructors", "always a String rather than a numeric type", "recalculated every time a new object is created", "shared by all instances of the class rather than unique to each one"], "answer": 3, "explanation": "A class variable is an attribute shared by all instances of the class, unlike an instance variable, which is unique per object. Class variables have no restriction on data type or where they may be used."},
  {"id": "3.1-basic-05", "course": "csa", "topic": "3.1", "tier": "basic", "lo": "3.1.A.4", "prompt": "A method named calculateArea() computes the area of a rectangle, but other classes that call the method do not know what formula is used inside it. This is an example of...", "choices": ["procedural abstraction", "data abstraction", "an instance variable", "a class variable"], "answer": 0, "explanation": "Procedural abstraction lets a method be used by knowing what it does, not how it does it internally. Data abstraction concerns hiding the representation of data, not the steps of a process, and this scenario involves no variables at all."},
  {"id": "3.1-basic-06", "course": "csa", "topic": "3.1", "tier": "basic", "lo": "3.1.A.4", "prompt": "A student's Robot class has one long method named runDance() that plays music, moves the robot forward, and then spins the robot around. The student rewrites the method into three smaller methods: playMusic(), moveForward(), and spin(). What is this technique called?", "choices": ["Data abstraction", "Method decomposition", "Encapsulating instance variables", "Declaring class variables"], "answer": 1, "explanation": "Breaking a larger behavior into smaller methods that each represent one task is method decomposition. No data is being hidden here, and no variables of any kind are being declared, so the other choices do not fit."},
  {"id": "3.1-basic-07", "course": "csa", "topic": "3.1", "tier": "basic", "lo": "3.1.A.5", "prompt": "A method header is written as follows.\npublic double convertToFahrenheit(double celsius)\nWhy is celsius included as a parameter instead of being hard-coded as a fixed value inside the method?", "choices": ["It makes the method run faster", "It prevents the method from returning a value", "It allows the method to be reused with many different Celsius values", "It allows the method to be declared without a return type"], "answer": 2, "explanation": "Using a parameter generalizes the method so it works with any Celsius value passed in, rather than one fixed value. Parameters have no effect on execution speed and the method still has a return type, double."},
  {"id": "3.1-basic-08", "course": "csa", "topic": "3.1", "tier": "basic", "lo": "3.1.A.2", "prompt": "Which best illustrates data abstraction?", "choices": ["Writing a comment that explains what a method returns", "Breaking a large method into several smaller methods", "Declaring a variable inside a loop", "Referring to a value as a customer's age without describing how the age is stored or computed"], "answer": 3, "explanation": "Data abstraction gives data a name, such as a customer's age, without referencing how it is represented internally. Comments, splitting methods, and loop variables all relate to other concepts, not to separating a data type's abstract meaning from its representation."},
  {"id": "3.1-basic-09", "course": "csa", "topic": "3.1", "tier": "basic", "lo": "3.1.A.7", "prompt": "Before writing any Java code for a new Song class, a student lists the song's title, artist, and length in seconds, along with a behavior that prints the song's information. What is the student doing?", "choices": ["Designing the class", "Debugging the class", "Compiling the class", "Testing the class with sample data"], "answer": 0, "explanation": "Listing attributes and behaviors in natural language before writing any code is exactly the class design process described in 3.1.A.7. Debugging, compiling, and testing all require code to already exist, which has not happened yet."},
  {"id": "3.1-basic-10", "course": "csa", "topic": "3.1", "tier": "basic", "lo": "3.1.A.3", "prompt": "A class representing a bank account needs to keep track of the current balance. Is balance an attribute or a behavior of the class?", "choices": ["A behavior, because the balance changes over time", "An attribute, because it is a piece of data stored by each account object", "A behavior, because it is calculated using a method", "An attribute, because it is shared by all accounts"], "answer": 1, "explanation": "Balance is a piece of data each account object stores, making it an attribute, not an action the object performs. It is not shared across accounts either, since each account has its own distinct balance."},
  {"id": "3.1-basic-11", "course": "csa", "topic": "3.1", "tier": "basic", "lo": "3.1.A.3", "prompt": "A class representing a car includes a way to determine how many miles the car has driven. Is calculating the total miles driven best modeled as an attribute or a behavior?", "choices": ["An attribute, since mileage is a number", "An attribute, since every car has the same value", "A behavior, since it describes an action the object can perform", "A behavior, since it can only return a String"], "answer": 2, "explanation": "Calculating and reporting total miles driven is an action the object performs, so it is best modeled as a behavior (method), regardless of what data type it returns. The underlying mileage value itself would be stored as an attribute, but the calculating action is a behavior."},
  {"id": "3.1-basic-12", "course": "csa", "topic": "3.1", "tier": "basic", "lo": "3.1.A.1", "prompt": "Which scenario best demonstrates the goal of abstraction?", "choices": ["A mechanic memorizes every wire in a car's engine", "A driver reads the car's complete engineering blueprints before each trip", "A driver disassembles the engine to check the oil level", "A driver operates a car using a steering wheel and pedals without needing to understand how the engine works internally"], "answer": 3, "explanation": "Abstraction hides irrelevant internal detail so a user can focus on the essential interface, exactly like a driver using a steering wheel and pedals without understanding the engine. The other options all involve engaging with unnecessary internal detail rather than hiding it."},
  {"id": "3.1-basic-13", "course": "csa", "topic": "3.1", "tier": "basic", "lo": "3.1.A.6", "prompt": "A method public int square(int n) originally computes n * n. A programmer changes the method body to compute the result using a different mathematical approach, but the method still takes one int parameter, still returns an int, and still produces the same results as before. What is true about code that calls square(int n)?", "choices": ["Calling code does not need to change, because the method signature and behavior are preserved", "All calling code must be rewritten to match the new internal approach", "The method can no longer be called from other classes", "The parameter name must be updated everywhere the method is called"], "answer": 0, "explanation": "As long as a method's signature and observable behavior stay the same, code that calls it does not need to change, even if the internal implementation changes. There is no reason calling code, access, or parameter naming would need to be touched."},
  {"id": "3.1-basic-14", "course": "csa", "topic": "3.1", "tier": "basic", "lo": "3.1.A.4", "prompt": "Instead of writing three nearly identical methods to print a welcome message for three different usernames, a student writes one method, printWelcome(String name), and calls it three times with different arguments. What benefit does this provide?", "choices": ["It allows the method to return more than one value", "It reduces duplicated code by reusing one generalized method", "It removes the need for the method to have a name", "It makes the variable name private"], "answer": 1, "explanation": "Generalizing the method with a parameter allows it to be reused instead of duplicating nearly identical code three times, which is a key benefit of procedural abstraction. The method still needs a name, still returns one value (or none), and this has nothing to do with variable access."},
  {"id": "3.1-basic-15", "course": "csa", "topic": "3.1", "tier": "basic", "lo": "3.1.A.3", "prompt": "A class representing a light bulb needs to track whether the bulb is currently on or off. Which data type is most appropriate for this attribute?", "choices": ["String", "int", "boolean", "double"], "answer": 2, "explanation": "A value with exactly two possible states, on or off, is most naturally represented with boolean. Using String, int, or double would work technically but would be a poor abstraction that allows meaningless values."},
  {"id": "3.1-intermediate-01", "course": "csa", "topic": "3.1", "tier": "intermediate", "lo": "3.1.A.3", "prompt": "A student is designing a class to represent a movie in a video rental app. The class should store the movie's title, its rating (e.g., \"PG\", \"PG-13\", \"R\"), and its runtime in minutes. Which set of attributes is most appropriate?", "choices": ["private String title;\nprivate String rating;\nprivate int runtime;", "private String title;\nprivate int rating;\nprivate String runtime;", "private String movieInfo;", "private int title;\nprivate String rating;\nprivate int runtime;"], "answer": 0, "explanation": "Title and rating are naturally text, while runtime is a whole number of minutes, so String, String, int is the most appropriate combination. Combining everything into one String loses the separation between distinct pieces of data, and the other options mismatch data types to their meaning."},
  {"id": "3.1-intermediate-02", "course": "csa", "topic": "3.1", "tier": "intermediate", "lo": "3.1.A.3", "prompt": "A student is developing a Thermostat class. The class should allow other classes to read and change the current target temperature, and it should track whether the heater is currently running. Which set of attributes and behaviors is most appropriate?", "choices": ["Attributes: targetTemperature, heaterRunning, getTargetTemperature(), setTargetTemperature(double). Behaviors: isHeaterRunning().", "Attributes: targetTemperature (double), heaterRunning (boolean). Behaviors: getTargetTemperature(), setTargetTemperature(double), isHeaterRunning().", "Attributes: getTargetTemperature(), isHeaterRunning(). Behaviors: targetTemperature, setTargetTemperature(double), heaterRunning.", "Attributes: targetTemperature (double). Behaviors: setTargetTemperature(double)."], "answer": 1, "explanation": "The correct design keeps the two pieces of data as attributes and the three actions as behaviors. The other options either misclassify methods as attributes and data as behaviors, or leave out tracking and reporting the heater's running status entirely."},
  {"id": "3.1-intermediate-03", "course": "csa", "topic": "3.1", "tier": "intermediate", "lo": "3.1.A.7", "prompt": "Consider the following partial class design.\npublic class Ticket\n{\n    - String eventName\n    - ____________\n    + String getEventName()\n    + ____________\n}\nThe class should store the ticket's price and allow other classes to retrieve it, but not change it directly. Which replacement for the blanks is most appropriate?", "choices": ["- double price / + void setPrice(double p)", "- String price / + String getPrice()", "- double price / + double getPrice()", "+ double price / + double getPrice()"], "answer": 2, "explanation": "Price should be a private double with only a public getter, since the class should not allow other classes to change it directly. A setPrice method would allow modification, a public attribute would remove encapsulation entirely, and String is the wrong data type for a numeric price."},
  {"id": "3.1-intermediate-04", "course": "csa", "topic": "3.1", "tier": "intermediate", "lo": "3.1.A.4", "prompt": "A student writes a single method named processOrder() that calculates a subtotal, applies a discount, adds tax, and prints a receipt, all within one long block of code. A classmate suggests splitting this into four separate methods: calculateSubtotal(), applyDiscount(), addTax(), and printReceipt(), each called in sequence from processOrder(). What is the primary benefit of this change?", "choices": ["The program will use less memory when it runs", "The method processOrder() no longer needs a return type", "The four smaller methods can be called without ever creating an object of the class", "Each smaller method represents one clear task, making the code easier to understand, test, and modify"], "answer": 3, "explanation": "Method decomposition breaks a large behavior into smaller methods, each representing one clear task, which improves readability, testability, and maintainability. Memory usage, return types, and whether an object must be created are unrelated to this refactoring."},
  {"id": "3.1-intermediate-05", "course": "csa", "topic": "3.1", "tier": "intermediate", "lo": "3.1.A.5", "prompt": "A student first writes a method public double tipAmount() that always calculates a 15% tip on a hard-coded bill of $40.00. The student then rewrites it as public double tipAmount(double bill, double tipRate). What is the main advantage of the second version?", "choices": ["It can be reused to calculate a tip for any bill amount and tip rate, not just $40.00 at 15%", "It no longer needs to return a value", "It can only be used once per program", "It automatically becomes a class variable"], "answer": 0, "explanation": "Adding parameters generalizes the method so it can be reused with a range of input values instead of one hard-coded case. The method still returns a double, can be called as many times as needed, and parameters have nothing to do with class variables."},
  {"id": "3.1-intermediate-06", "course": "csa", "topic": "3.1", "tier": "intermediate", "lo": "3.1.A.2", "prompt": "A GPS application displays a user's position as \"123 Main Street\" instead of showing raw latitude and longitude coordinates and the internal calculations used to determine them. This is an example of...", "choices": ["procedural abstraction, because a method is being called", "data abstraction, because the location is represented in a way that hides the underlying details of how it is stored and computed", "a class variable, because all users share the same address", "method decomposition, because multiple methods were combined"], "answer": 1, "explanation": "Naming the location as an address while hiding the raw coordinate representation is data abstraction. This scenario is not about a shared class variable, nor is it about combining or naming a process, which would be procedural abstraction or method decomposition."},
  {"id": "3.1-intermediate-07", "course": "csa", "topic": "3.1", "tier": "intermediate", "lo": "3.1.A.3", "prompt": "Two students are designing a Student class for a school app. Every Student object needs its own gradeLevel, but all Student objects in the app should share the same value for schoolName, since every student attends the same school. Which describes the most appropriate choice of variable types?", "choices": ["gradeLevel should be a class variable; schoolName should be an instance variable", "Both gradeLevel and schoolName should be instance variables", "gradeLevel should be an instance variable; schoolName should be a class variable", "Both gradeLevel and schoolName should be class variables"], "answer": 2, "explanation": "Since gradeLevel differs from student to student, it should be an instance variable, while schoolName is identical for every student and is best represented as a class variable shared by all instances. Making both the same type would either force every student to share a grade level or unnecessarily duplicate the shared school name in every object."},
  {"id": "3.1-intermediate-08", "course": "csa", "topic": "3.1", "tier": "intermediate", "lo": "3.1.A.7", "prompt": "A student is designing a Recipe class for a cooking app. The class should represent the recipe's name, the number of servings it makes, and a behavior that scales the recipe to a new number of servings. Which natural-language design best captures this?", "choices": ["Attributes: name (String), servings (int), scaleServings (String).", "Attributes: name (String). Behaviors: servings(int), scaleServings(int newServings).", "Attributes: recipeData (String) containing the name and servings combined. Behavior: scaleServings(int newServings).", "Attributes: name (String), servings (int). Behavior: scaleServings(int newServings) \u2014 adjusts ingredient amounts based on the new number of servings."], "answer": 3, "explanation": "The correct design keeps name and servings as separate, appropriately typed attributes and clearly describes scaleServings as a behavior that performs an action. The other designs either misclassify scaleServings as an attribute, misclassify servings as a behavior, or collapse distinct data into one combined String."},
  {"id": "3.1-intermediate-09", "course": "csa", "topic": "3.1", "tier": "intermediate", "lo": "3.1.A.4", "prompt": "A Store class has three methods: printMorningReport(), printAfternoonReport(), and printEveningReport(). Each method contains identical code to format and print the store's name and address, followed by different sales figures for that time of day. Which change best applies procedural abstraction to reduce duplication?", "choices": ["Extract the shared formatting and printing code for the name and address into a single new method, and call that new method from all three existing methods", "Combine all three methods into one method with no parameters", "Copy the sales-figure code from one method into the other two methods so all three match exactly", "Make the three methods class variables instead of methods"], "answer": 0, "explanation": "Extracting the duplicated code into its own method and calling it from each original method removes the duplication while preserving each method's distinct sales calculation. Combining everything into one parameterless method or copying more code would not remove the duplication, and methods cannot be turned into class variables."},
  {"id": "3.1-intermediate-10", "course": "csa", "topic": "3.1", "tier": "intermediate", "lo": "3.1.A.6", "prompt": "A method public double getAverage(double a, double b) currently returns the average using the expression (a + b) / 2. Which of the following changes would break code that already calls getAverage(double a, double b), assuming that code was written to use the original version?", "choices": ["Changing the method's internal variable names used to store intermediate results", "Changing the method's parameter list to public double getAverage(double a, double b, double c)", "Rewriting the calculation using a different but mathematically equivalent expression", "Adding a comment above the method describing what it does"], "answer": 1, "explanation": "Changing the parameter list changes the method's signature, so existing calls with only two arguments would no longer match and would break. Renaming internal variables, rewriting the calculation equivalently, and adding comments do not change the signature or observable behavior, so existing calls still work."},
  {"id": "3.1-intermediate-11", "course": "csa", "topic": "3.1", "tier": "intermediate", "lo": "3.1.A.3", "prompt": "A student is developing a class to represent a single weather observation, including the temperature in degrees and whether precipitation was recorded that day. Which set of attributes is most appropriate?", "choices": ["private String temperature;\nprivate String precipitation;", "private double temperature;\nprivate double precipitation;", "private double temperature;\nprivate boolean precipitation;", "private boolean temperature;\nprivate boolean precipitation;"], "answer": 2, "explanation": "Temperature is naturally a numeric value, so double is appropriate, while whether precipitation occurred is a true/false condition, best represented with boolean. Using String or double for a yes/no value, or boolean for temperature, would be an inappropriate data-type choice."},
  {"id": "3.1-intermediate-12", "course": "csa", "topic": "3.1", "tier": "intermediate", "lo": "3.1.A.7", "prompt": "Consider the following partial class design.\npublic class LibraryCard\n{\n    - String ownerName\n    - int cardNumber\n    - ____________\n    + String getOwnerName()\n    + int getCardNumber()\n    + ____________\n}\nThe class should track whether the card is currently active and allow other classes to check this status. Which replacement for the blanks is most appropriate?", "choices": ["- String active / + void setActive(String s)", "+ boolean active / + boolean isActive()", "- boolean active / - boolean isActive()", "- boolean active / + boolean isActive()"], "answer": 3, "explanation": "A true/false status is best represented with a private boolean, paired with a public method to check it, matching the naming convention isActive(). Making the attribute public breaks encapsulation, making the checking method private would prevent other classes from checking status, and String is the wrong data type for a true/false value."},
  {"id": "3.1-intermediate-13", "course": "csa", "topic": "3.1", "tier": "intermediate", "lo": "3.1.A.1", "prompt": "A large software project is built by a team of 12 programmers, each responsible for different classes. Why is abstraction especially valuable in this setting?", "choices": ["It allows each programmer to use another programmer's class correctly by knowing what it does, without needing to understand or worry about how it is implemented internally", "It guarantees that the program will contain no logic errors", "It ensures that every class in the project has the exact same number of methods", "It eliminates the need for programmers to test their own code"], "answer": 0, "explanation": "Abstraction manages complexity by letting programmers rely on what a class does rather than how it works internally, which is essential when many people collaborate on different classes. It does not guarantee error-free code, does not require identical method counts, and does not remove the need for testing."},
  {"id": "3.1-intermediate-14", "course": "csa", "topic": "3.1", "tier": "intermediate", "lo": "3.1.A.3", "prompt": "A student is developing a Book class for a library system. The class should allow other classes to check whether the book is checked out and to mark it as checked out or returned. Which set of attributes and behaviors is most appropriate?", "choices": ["Attributes: checkedOut (boolean), isCheckedOut(), checkOut(), returnBook(). Behaviors: none.", "Attributes: checkedOut (boolean). Behaviors: isCheckedOut(), checkOut(), returnBook().", "Attributes: isCheckedOut(), checkOut(), returnBook(). Behaviors: checkedOut (boolean).", "Attributes: none. Behaviors: checkedOut (boolean), isCheckedOut(), checkOut(), returnBook()."], "answer": 1, "explanation": "checkedOut is the piece of data the class stores, so it belongs as an attribute, while isCheckedOut(), checkOut(), and returnBook() are all actions, so they belong as behaviors. The other options incorrectly mix methods into the attribute list or the data value into the behavior list."},
  {"id": "3.1-intermediate-15", "course": "csa", "topic": "3.1", "tier": "intermediate", "lo": "3.1.A.5", "prompt": "A student writes the following method that always converts a temperature of exactly 100 degrees Celsius to Fahrenheit.\npublic double convert()\n{\n    double celsius = 100;\n    return celsius * 9.0 / 5.0 + 32;\n}\nWhich redesigned version best applies procedural abstraction so the method can convert any Celsius temperature?", "choices": ["public double convert()\n{\n    double celsius = 212;\n    return celsius * 9.0 / 5.0 + 32;\n}", "private double celsius;\npublic double convert()\n{\n    return celsius * 9.0 / 5.0 + 32;\n}", "public double convert(double celsius)\n{\n    return celsius * 9.0 / 5.0 + 32;\n}", "public void convert(double celsius)\n{\n    celsius * 9.0 / 5.0 + 32;\n}"], "answer": 2, "explanation": "Adding celsius as a parameter generalizes the method so it can convert any Celsius value passed as an argument. The other options either hard-code a different fixed value, rely on an instance variable that still is not set from outside, or fail to return a value at all."},
  {"id": "3.1-complex-01", "course": "csa", "topic": "3.1", "tier": "complex", "lo": "3.1.A.7", "prompt": "A student is designing a class to represent a ParkingSpot in a garage management system. Each parking spot has a unique spot number, a level (floor) in the garage, and a status indicating whether it is currently occupied. The class should also allow other classes to reserve the spot and to release it. A student proposes the following four candidate designs.\nI. Attributes: spotNumber (int), level (int), occupied (boolean). Behaviors: reserve(), release(), isOccupied().\nII. Attributes: spotNumber (int), level (int), occupied (boolean), reserve(), release(). Behaviors: isOccupied().\nIII. Attributes: spotInfo (String) combining spot number, level, and status into one value. Behaviors: reserve(), release(), isOccupied().\nIV. Attributes: spotNumber (int), level (String), occupied (int). Behaviors: reserve(), release(), isOccupied().\nWhich design most appropriately separates attributes and behaviors and uses the most appropriate data types?", "choices": ["II", "III", "IV", "I"], "answer": 3, "explanation": "Design I keeps each piece of data as a correctly typed attribute and each action as a distinct behavior. Design II misclassifies reserve() and release() as attributes, Design III collapses three distinct pieces of data into a single String, and Design IV uses inappropriate data types for level and occupied."},
  {"id": "3.1-complex-02", "course": "csa", "topic": "3.1", "tier": "complex", "lo": "3.1.A.3", "prompt": "A student is designing a ChoirMember class for a school choir roster app. Each member has their own name and vocal part (such as \"soprano\" or \"bass\"). All ChoirMember objects should share one common value representing the choir's concert date, since the entire choir performs on the same date. Which of the following correctly matches each attribute to the most appropriate variable type?", "choices": ["name: class variable; vocalPart: instance variable; concertDate: instance variable", "name: instance variable; vocalPart: class variable; concertDate: class variable", "name: class variable; vocalPart: class variable; concertDate: instance variable", "name: instance variable; vocalPart: instance variable; concertDate: class variable"], "answer": 3, "explanation": "Name and vocal part are unique to each member, so they should be instance variables, while concertDate is identical for every member and is best modeled as a shared class variable. The other options incorrectly make member-specific data shared or shared data member-specific."},
  {"id": "3.1-complex-03", "course": "csa", "topic": "3.1", "tier": "complex", "lo": "3.1.A.4", "prompt": "A student writes a single method named generateInvoice() that (1) calculates the cost of items purchased, (2) calculates sales tax, (3) calculates a loyalty discount, and (4) formats and prints the final invoice. A classmate suggests breaking this into four separate methods, each handling one of these four tasks, all called in order from generateInvoice(). Which of the following are legitimate benefits of this refactoring?\nI. Each smaller method can be tested and debugged independently of the others.\nII. If the tax calculation logic needs to change later, only the tax method needs to be modified.\nIII. The refactored version is guaranteed to run faster than the original single method.\nIV. Other methods in the class could reuse the discount-calculation method if needed elsewhere.", "choices": ["I and III only", "II and III only", "III only", "I, II, and IV only"], "answer": 3, "explanation": "Method decomposition genuinely improves independent testability (I), isolates future changes to one method (II), and enables reuse of extracted methods (IV). It does not guarantee faster execution (III), since decomposition is about clarity and maintainability, not runtime performance."},
  {"id": "3.1-complex-04", "course": "csa", "topic": "3.1", "tier": "complex", "lo": "3.1.A.7", "prompt": "Consider the following partial class design for tracking a savings account.\npublic class SavingsAccount\n{\n    - double balance\n    - double interestRate\n    - ____________\n    + double getBalance()\n    + void deposit(double amount)\n    + ____________\n}\nThe class should allow other classes to find out the current interest rate but should not allow other classes to change it directly, and it should also track the account holder's name. Which replacement for the blanks is most appropriate?", "choices": ["- String accountHolder / + void setInterestRate(double rate)", "+ String accountHolder / + double getInterestRate()", "- int accountHolder / + void setAccountHolder(String name)", "- String accountHolder / + double getInterestRate()"], "answer": 3, "explanation": "accountHolder should be a private String attribute, and a public getInterestRate() method provides read-only access to interestRate without allowing it to be changed. Adding a setInterestRate method would allow modification, which the design explicitly disallows, making a public attribute or an int type for a name both inappropriate."},
  {"id": "3.1-complex-05", "course": "csa", "topic": "3.1", "tier": "complex", "lo": "3.1.A.4", "prompt": "A GradeBook class has three methods: computeQuizAverage(), computeTestAverage(), and computeFinalAverage(). Each of these three methods contains identical code near the beginning that validates whether the class has at least one recorded score before performing its calculation. A student wants to apply procedural abstraction to eliminate this duplication. Which change best achieves this?", "choices": ["Delete the validation code from all three methods so the program compiles faster", "Combine all three averaging methods into a single method with three parameters, one for each average", "Rewrite the validation code slightly differently in each method so a reader can tell them apart", "Extract the validation code into a new method, such as hasRecordedScores(), and call that new method from within each of the three original methods"], "answer": 3, "explanation": "Extracting the shared validation logic into its own method and calling it from each averaging method removes duplication while preserving each method's distinct purpose. Deleting the validation removes needed functionality, rewriting it differently in each place increases duplication rather than reducing it, and combining unrelated averages into one method does not address the duplicated validation code."},
  {"id": "3.1-complex-06", "course": "csa", "topic": "3.1", "tier": "complex", "lo": "3.1.A.3", "prompt": "A student is designing a WeatherStation class. The class should record the current temperature in degrees Fahrenheit, the current wind speed in miles per hour, and whether a storm warning is currently active. A student proposes the following candidate attribute lists.\nI. private int temperature; private int windSpeed; private String stormWarning;\nII. private double temperature; private double windSpeed; private boolean stormWarning;\nIII. private String temperature; private String windSpeed; private boolean stormWarning;\nIV. private double temperature; private double windSpeed; private int stormWarning;\nWhich of the four candidate attribute lists is most appropriate?", "choices": ["I", "III", "IV", "II"], "answer": 3, "explanation": "Temperature and wind speed are naturally decimal measurements, so double is appropriate, and a storm warning is a true/false condition, best represented with boolean, which matches List II exactly. The other lists use int or String for a true/false value or String for numeric measurements, both inappropriate type choices."},
  {"id": "3.1-complex-07", "course": "csa", "topic": "3.1", "tier": "complex", "lo": "3.1.A.6", "prompt": "A large ride-sharing app has a method public double calculateFare(double miles, double minutes) used throughout the codebase by dozens of other classes to compute a trip's fare. The company later decides to change the internal formula used to calculate the fare, accounting for a new surge-pricing algorithm, but the method still takes a distance in miles and a duration in minutes, and still returns a double representing the fare. Which of the following best explains why this change does not require modifying the dozens of classes that call calculateFare()?", "choices": ["The method's signature and its documented behavior (what it computes and returns) remain the same, so calling code depends only on that abstraction, not on the internal formula", "Java automatically rewrites all calling code whenever a method's body changes", "The calling classes never actually call calculateFare() directly, only calculateFare()'s instance variables", "The surge-pricing algorithm is stored as a class variable that all calling classes share"], "answer": 0, "explanation": "Procedural abstraction means calling code relies only on a method's signature and what it does, so as long as those stay the same, the internal formula can change freely without breaking any caller. Java does not automatically rewrite code, calling classes do interact with the method directly, and nothing in the scenario involves a shared class variable."},
  {"id": "3.1-complex-08", "course": "csa", "topic": "3.1", "tier": "complex", "lo": "3.1.A.7", "prompt": "A student is designing an Employee class for a payroll system. Each employee has a name, an hourly pay rate, and a total number of hours worked in the current pay period. The class should allow other classes to retrieve the employee's total pay for the period without knowing the exact calculation used. Which design best reflects appropriate abstraction?", "choices": ["Attributes: name (String), hourlyRate (double), hoursWorked (double), all private. Behavior: public double getTotalPay(), which internally multiplies hourlyRate by hoursWorked and returns the result.", "Attributes: name (String), totalPay (double), all public, with no behaviors, requiring every other class to compute totalPay itself using hourlyRate and hoursWorked.", "Attributes: name (String), hourlyRate (double), hoursWorked (double), totalPay (String), all private, with no behaviors.", "Attributes: name (String), all private. Behaviors: hourlyRate(double), hoursWorked(double), getTotalPay(), each storing a value rather than performing a calculation or returning data."], "answer": 0, "explanation": "Keeping the raw data private and exposing a getTotalPay() method lets other classes obtain the total pay without knowing or depending on the calculation used, which is proper data and procedural abstraction. The other designs either force calling classes to compute the value themselves, store a computed total as an inappropriate String with no way to retrieve it, or misclassify data-holding attributes as behaviors."},
  {"id": "3.1-complex-09", "course": "csa", "topic": "3.1", "tier": "complex", "lo": "3.1.A.3", "prompt": "A student is designing a TournamentPlayer class for a chess tournament app. Every player has their own name and current score, which differ from player to player. The student also wants every TournamentPlayer object to have access to one shared value representing the total number of rounds in the tournament, since this number is the same for every player and every player object should reflect any change to it immediately. Which classification of these three pieces of data is most appropriate?", "choices": ["name and score should be instance variables; totalRounds should be a class variable", "name, score, and totalRounds should all be instance variables", "name should be a class variable; score and totalRounds should be instance variables", "name, score, and totalRounds should all be class variables"], "answer": 0, "explanation": "Name and score vary per player, so they should be instance variables, while totalRounds is one shared value that every player object should reflect immediately, which is exactly what a class variable provides. Making totalRounds an instance variable would give each player its own separate copy that would not automatically update for everyone, and making name or score a class variable would incorrectly force all players to share those values."},
  {"id": "3.1-complex-10", "course": "csa", "topic": "3.1", "tier": "complex", "lo": "3.1.A.4", "prompt": "A student writes a single method named runGameTurn() that (1) reads the player's move, (2) validates whether the move is legal, (3) updates the game board, and (4) checks whether the game has been won. Which of the following statements about decomposing runGameTurn() into four separate methods, each responsible for one task and each called from runGameTurn(), are true?\nI. The decomposition guarantees that the game logic itself will contain fewer bugs.\nII. Each individual task becomes easier to understand and test in isolation.\nIII. Other parts of the program could potentially reuse the move-validation method for a different purpose, such as checking legal moves before offering a hint.\nIV. The decomposition eliminates the need for runGameTurn() to call any other methods.", "choices": ["I and IV only", "II and III only", "I, II, and III only", "II, III, and IV only"], "answer": 1, "explanation": "Decomposing into focused methods genuinely improves independent understandability and testability (II) and opens the door to reusing a method like move-validation elsewhere (III). It does not guarantee fewer bugs (I), and runGameTurn() would still need to call the four extracted methods, not eliminate calling other methods (IV)."},
  {"id": "3.1-complex-11", "course": "csa", "topic": "3.1", "tier": "complex", "lo": "3.1.A.3", "prompt": "A student is designing a RentalCar class for a car rental company. The class should allow other classes to determine the car's current mileage, to record additional miles driven, and to determine whether the car is due for maintenance once its mileage exceeds 5,000 miles since its last service. Which set of attributes and behaviors is most appropriate?", "choices": ["Attributes: mileage (int), milesSinceService (int), getMileage(), addMiles(int), needsMaintenance(). Behaviors: none.", "Attributes: mileage (int), milesSinceService (int). Behaviors: getMileage(), addMiles(int), needsMaintenance(), each operating on the two attributes to report or update mileage information.", "Attributes: getMileage(), addMiles(int), needsMaintenance(). Behaviors: mileage (int), milesSinceService (int).", "Attributes: mileageInfo (String) combining all mileage data into one value. Behaviors: getMileage(), addMiles(int), needsMaintenance()."], "answer": 1, "explanation": "Keeping mileage and milesSinceService as attributes and the three actions as behaviors that operate on that data reflects a correct and appropriately typed design. The other options either misclassify the methods as attributes, misclassify the data as behaviors, or collapse distinct numeric data into a single combined String."},
  {"id": "3.1-complex-12", "course": "csa", "topic": "3.1", "tier": "complex", "lo": "3.1.A.5", "prompt": "A student originally writes three separate methods to compute a discounted price: tenPercentOff(double price), twentyPercentOff(double price), and thirtyPercentOff(double price), each hard-coding a different discount percentage. The student then replaces all three with a single method, applyDiscount(double price, double percentOff). A classmate argues this is a strict improvement. Which statement best supports the classmate's argument while also being accurate?", "choices": ["The single method is faster to execute than any of the three original methods", "The single method generalizes the discount calculation using a parameter, so it can compute any discount percentage without needing a separate method for each one, reducing duplicated code", "The single method no longer needs to return a value, since discounts are optional", "The single method automatically becomes shared by all instances of the class as a class variable"], "answer": 1, "explanation": "Adding percentOff as a parameter generalizes the calculation so one method can handle any discount percentage, eliminating the need for a separate hard-coded method per percentage and reducing duplication. There is no reason this change affects execution speed, the method still returns a value, and methods cannot become class variables."},
  {"id": "3.1-complex-13", "course": "csa", "topic": "3.1", "tier": "complex", "lo": "3.1.A.7", "prompt": "A student is designing a class to represent a LibraryBook that can be checked out and returned, and that also charges a late fee once it is overdue. The student drafts the following partial design.\npublic class LibraryBook\n{\n    - String title\n    - boolean checkedOut\n    - int daysOverdue\n    + String getTitle()\n    + boolean isCheckedOut()\n    + void checkOut()\n    + void returnBook()\n    + double calculateLateFee()\n}\nWhich statement correctly evaluates this design?", "choices": ["The design is flawed because checkedOut and daysOverdue should be declared as public so other classes can modify them directly", "The design is flawed because calculateLateFee() should be an attribute rather than a behavior, since it produces a numeric value", "The design is reasonable because it separates the book's data (title, checkedOut, daysOverdue) from its behaviors (getTitle, isCheckedOut, checkOut, returnBook, calculateLateFee), keeping the instance variables private", "The design is flawed because a class can only have one behavior that returns a value"], "answer": 2, "explanation": "The design correctly keeps all stored data private and exposes clearly separated behaviors, matching good class-design practice. Making the attributes public would remove encapsulation rather than fix a flaw, a method that returns a numeric value is still a behavior rather than an attribute, and there is no such restriction limiting a class to one value-returning method."},
  {"id": "3.1-complex-14", "course": "csa", "topic": "3.1", "tier": "complex", "lo": "3.1.A.2", "prompt": "A Fraction class stores a fraction using two private instance variables, numerator and denominator, and provides a method getDecimalValue() that returns the fraction's value as a double. A programmer using the Fraction class in a separate program only ever calls getDecimalValue() and never accesses numerator or denominator directly. Later, the Fraction class is rewritten to store the value internally as a single double called decimalValue instead of numerator and denominator, and getDecimalValue() is updated to simply return decimalValue. What best describes the effect of this change on the separate program?", "choices": ["The separate program will no longer compile, because the internal representation of Fraction changed", "The separate program must be rewritten to reference decimalValue directly", "The separate program is unaffected, because it only relied on the data abstraction provided by getDecimalValue() and never depended on the internal representation", "The separate program will now return incorrect results, because numerator and denominator no longer exist"], "answer": 2, "explanation": "Because the separate program only ever used getDecimalValue() and never referenced numerator or denominator directly, it depended only on the data abstraction, not the internal representation, so it is unaffected by the change. It does not need to be rewritten, will still compile, and will still return correct results since getDecimalValue()'s behavior is preserved."},
  {"id": "3.1-complex-15", "course": "csa", "topic": "3.1", "tier": "complex", "lo": "3.1.A.6", "prompt": "A student is designing a Temperature class meant to store a temperature reading in degrees Celsius and provide a way to obtain the equivalent value in degrees Fahrenheit without storing it separately. Consider the following four candidate designs.\nI.\nprivate double celsius;\npublic double getFahrenheit()\n{\n    return celsius * 9.0 / 5.0 + 32;\n}\nII.\nprivate double celsius;\nprivate double fahrenheit;\npublic double getFahrenheit()\n{\n    return fahrenheit;\n}\nIII.\nprivate double celsius;\nprivate double fahrenheit;\npublic void getFahrenheit()\n{\n    fahrenheit = celsius * 9.0 / 5.0 + 32;\n}\nIV.\npublic double celsius;\npublic double getFahrenheit()\n{\n    return celsius * 9.0 / 5.0 + 32;\n}\nWhich of these designs most appropriately uses procedural abstraction to compute the Fahrenheit value on demand while also protecting the class's data through encapsulation?", "choices": ["IV", "III", "I", "II"], "answer": 2, "explanation": "Design I stores only celsius privately and computes the Fahrenheit value on demand inside a getter that returns a value, which is both correct procedural abstraction and proper encapsulation. Design II stores an unused, never-updated fahrenheit field, Design III never returns the computed value at all, and Design IV exposes celsius as public, breaking encapsulation."},
  {"id": "3.2-basic-01", "course": "csa", "topic": "3.2", "tier": "basic", "lo": "3.2.A.1", "prompt": "A team building a hospital medication-dosage calculator skips testing with unusual patient weights to save time before a deadline. What is the most likely consequence?", "choices": ["Decreased system reliability, since the program may fail under conditions that were never tested", "Increased system reliability, since fewer tests mean fewer bugs are introduced", "The program automatically becomes easier to reuse as open source", "The program's economic impact on hospitals will be eliminated"], "answer": 0, "explanation": "Skipping tests for atypical patient weights means the program's behavior in those cases was never verified, which decreases system reliability. Reducing testing never increases reliability, and testing decisions have no bearing on open-source status or economic impact."},
  {"id": "3.2-basic-02", "course": "csa", "topic": "3.2", "tier": "basic", "lo": "3.2.A.2", "prompt": "A free app helps farmers predict irrigation schedules from local weather data. Which of the following is a true statement about this program?", "choices": ["Because it was designed to help farmers, it cannot have any negative effects.", "The program could have unintended harmful effects beyond its intended use, such as farmers over-relying on it during unusual weather patterns.", "The program automatically becomes open source simply because it is offered free of charge.", "Releasing the program will directly increase the reliability of unrelated agricultural software."], "answer": 1, "explanation": "A program built to help can still produce unintended harmful effects beyond its original purpose, such as encouraging over-reliance during weather the model wasn't designed for. Being free does not make software open source, and one program's release does not affect the reliability of unrelated software."},
  {"id": "3.2-basic-03", "course": "csa", "topic": "3.2", "tier": "basic", "lo": "3.2.A.3", "prompt": "A student wants to include a sorting algorithm implementation found on a public GitHub repository that is explicitly labeled with an open-source license permitting reuse. What should the student do?", "choices": ["Avoid using it entirely, since all reused code requires payment", "Rewrite the algorithm from scratch, since open-source code cannot legally be used in student projects", "Use the code according to the terms of its open-source license, giving credit where required", "Use the code freely with no restrictions, since open source means no license terms ever apply"], "answer": 2, "explanation": "When code is explicitly published under an open-source license, using it according to that license's terms, including any attribution requirement, is exactly what such licenses allow. Open source does not require payment, and it does not mean there are no terms at all."},
  {"id": "3.2-basic-04", "course": "csa", "topic": "3.2", "tier": "basic", "lo": "3.2.A.1", "prompt": "A developer releases a budgeting app after testing it only on the developer's own phone model and operating system version. Which of the following best describes a risk this creates?", "choices": ["The app will run identically on every device regardless of hardware or OS differences", "The app's intellectual property protection will be weakened", "The app will automatically qualify as open source", "The app may fail to perform as expected under conditions, such as other devices or OS versions, that were not tested"], "answer": 3, "explanation": "Testing on only one device and OS configuration leaves behavior on all other configurations unverified, creating real risk of unexpected failure elsewhere. This is a reliability issue, not one connected to intellectual property or open-source status."},
  {"id": "3.2-basic-05", "course": "csa", "topic": "3.2", "tier": "basic", "lo": "3.2.A.2", "prompt": "A ride-sharing scheduling program is created to reduce commuter wait times in a mid-sized city. Which of the following is most accurate regarding its potential impact?", "choices": ["The program could produce both beneficial effects, like shorter wait times, and harmful ones, like increased traffic in certain neighborhoods.", "Software designed to solve a problem can only ever produce beneficial effects.", "The program's economic impact is limited strictly to the company that created it.", "Because the goal was to help commuters, no further testing of the program is required."], "answer": 0, "explanation": "Software created to solve a real problem can produce genuine benefits alongside genuine unintended harms at the same time. Good intent does not eliminate the need for testing, and economic effects are not confined only to the creating company."},
  {"id": "3.2-basic-06", "course": "csa", "topic": "3.2", "tier": "basic", "lo": "3.2.A.3", "prompt": "A small studio wants to include a commercial physics engine, which is not published as open source, in their new video game. What must the studio do before integrating the engine into their game?", "choices": ["Nothing, since any code that improves a program's performance may be used freely.", "Obtain permission from the engine's owner, which often requires purchasing a license, before integrating the code.", "Publish their own game as open source in exchange for using the engine.", "Rewrite the engine's comments so the origin of the code cannot be identified."], "answer": 1, "explanation": "Proprietary, non-open-source code generally requires the owner's permission, and often a purchased license, before legal integration into another product. Code cannot be used freely simply because it improves performance."},
  {"id": "3.2-basic-07", "course": "csa", "topic": "3.2", "tier": "basic", "lo": "3.2.A.1", "prompt": "Which of the following actions would best help a programmer maximize the reliability of a new fitness-tracking application?", "choices": ["Releasing the application as soon as the main features compile without errors", "Limiting testing to the scenario the programmer personally uses most often", "Testing the application under a wide variety of conditions, including unusual inputs and device types", "Removing all error-handling code to simplify the program before release"], "answer": 2, "explanation": "Testing under a wide range of conditions, including edge cases, is the best way to maximize system reliability. Releasing after minimal compilation, testing only one familiar scenario, or removing error handling all increase the risk of unexpected failures."},
  {"id": "3.2-basic-08", "course": "csa", "topic": "3.2", "tier": "basic", "lo": "3.2.A.2", "prompt": "A company creates a facial-recognition attendance system for schools to reduce the time spent taking daily attendance. Which of the following is most accurate?", "choices": ["Because the system was designed for a beneficial purpose, it cannot raise any concerns.", "The system's only possible effects are economic, since it does not involve legal or cultural considerations.", "The system will automatically become free and open source once adopted by schools.", "The system, though designed to solve a real problem, could raise unintended concerns such as privacy or fairness issues for some students."], "answer": 3, "explanation": "A program built for a legitimate purpose can still raise unintended concerns, such as privacy or fairness, beyond its original goal. Good intentions do not make software immune to negative effects, nor do they determine its open-source status."},
  {"id": "3.2-intermediate-01", "course": "csa", "topic": "3.2", "tier": "intermediate", "lo": "3.2.A.1", "prompt": "A transportation-scheduling program passed all tests using data from a large city with dense bus routes. When deployed in a rural county with sparse routes and spotty GPS coverage, the program frequently crashed. Which explanation best identifies the underlying issue?", "choices": ["The program was not tested under the range of conditions it would actually encounter, so its reliability in the new environment could not be guaranteed.", "The program's source code was not published as open source, causing it to fail in new counties.", "Rural deployment automatically voids a program's licensing agreement.", "The program's economic impact on the rural county caused the crashes."], "answer": 0, "explanation": "A program only verified in one environment provides no guarantee of reliable behavior in a very different environment; this is a testing gap, not a licensing or economic issue. Deployment location has no automatic effect on licensing agreements."},
  {"id": "3.2-intermediate-02", "course": "csa", "topic": "3.2", "tier": "intermediate", "lo": "3.2.A.3", "prompt": "A recent graduate is building a resume-building website and finds a nicely designed CSS template online. The template's page states \"All rights reserved; contact author for licensing,\" with no open-source license mentioned. The graduate is tempted to use it anyway because rewriting the design would take extra time. What is the most appropriate action?", "choices": ["Use the template freely, since anything found publicly on the internet is automatically open source.", "Contact the author to obtain permission, and likely pay for a license, before using the template in the website.", "Use the template but remove the author's name from any files to avoid detection.", "Use the template only on weekends, when licensing terms are assumed not to apply."], "answer": 1, "explanation": "A 'rights reserved' notice with no open-source license means permission, and often payment, is required before use. Public visibility on the internet does not make content open source, and removing attribution or timing usage differently does not change the legal requirement."},
  {"id": "3.2-intermediate-03", "course": "csa", "topic": "3.2", "tier": "intermediate", "lo": "3.2.A.2", "prompt": "A streaming platform introduces a recommendation algorithm designed to help users discover independent musicians who might otherwise go unnoticed. Over time, some independent artists report increased sales, while others note that the algorithm tends to favor songs that are shorter and more \"catchy,\" gradually shifting what kinds of music get produced. Which of the following best characterizes this situation?", "choices": ["Because the algorithm was designed with good intentions, any change in what music gets produced does not count as an impact of the program.", "The shift in music styles proves the algorithm was published without an open-source license.", "The algorithm demonstrates that software designed to solve one problem can produce both intended benefits and unintended cultural effects.", "The algorithm's effect on music styles is strictly a reliability issue and unrelated to societal impact."], "answer": 2, "explanation": "The algorithm helps some artists while also reshaping what kind of music gets made, showing software can produce both intended benefits and unintended cultural effects at once. This is a societal/cultural impact issue, unrelated to licensing or reliability."},
  {"id": "3.2-intermediate-04", "course": "csa", "topic": "3.2", "tier": "intermediate", "lo": "3.2.A.1", "prompt": "A team building software to monitor river water levels for flood warnings must decide between shipping the product two months earlier with reduced testing, or delaying the release to test extensively under storm conditions, sensor outages, and rapid data spikes. A manager argues that shipping early is worth the risk because \"most days are normal.\" Which response best addresses the manager's reasoning?", "choices": ["The manager is correct, since programs only need to handle the most common conditions to be considered reliable.", "Reduced testing has no effect on reliability as long as the code compiles without errors.", "The team should skip testing entirely and instead purchase a license for flood data to guarantee reliability.", "Because flood warnings matter most during unusual conditions, skipping tests for exactly those conditions would leave the system's reliability unverified when it matters most."], "answer": 3, "explanation": "Flood monitoring matters most precisely during unusual, high-stress conditions, so skipping testing for exactly those scenarios leaves real-world reliability unverified when it counts. Handling only common conditions is not sufficient, and licensing has no bearing on this tradeoff."},
  {"id": "3.2-intermediate-05", "course": "csa", "topic": "3.2", "tier": "intermediate", "lo": "3.2.A.3", "prompt": "A hobbyist programmer publishes a puzzle-generating library on a code-sharing site under an open-source license that permits free use and modification, provided any derivative work credits the original author. Another developer uses the library inside a commercial mobile game but does not mention the original author anywhere in the game or its credits. Which of the following best describes the situation?", "choices": ["The developer has violated the terms of the open-source license by not providing the required attribution, even though the code itself was free to use.", "No violation occurred, because open-source code can be used in any way without restriction.", "The developer must now make the entire mobile game open source in response.", "The violation only matters if the mobile game becomes unreliable."], "answer": 0, "explanation": "Even though the code was free to use, the license's attribution condition is still a binding term; failing to credit the author violates that license despite the code being open source. Open-source licenses commonly include conditions like attribution."},
  {"id": "3.2-intermediate-06", "course": "csa", "topic": "3.2", "tier": "intermediate", "lo": "3.2.A.2", "prompt": "A city deploys a pothole-reporting app that lets residents photograph and log road damage so crews can prioritize repairs. After a year, data shows that potholes get fixed fastest in neighborhoods with the most smartphone users and slowest in neighborhoods with older populations and less smartphone access. Which of the following best explains this outcome?", "choices": ["The app cannot be responsible for this pattern, since its intended purpose was purely beneficial.", "A program designed to solve one problem, faster repairs, can create an unintended harmful effect, such as unequal service across neighborhoods, beyond its original purpose.", "The uneven repair pattern is solely a system-reliability issue caused by insufficient testing.", "The uneven repair pattern indicates the app was not released under an open-source license."], "answer": 1, "explanation": "A program meant to solve one problem relied on a resource, smartphone ownership, that isn't evenly distributed, producing an unintended harmful effect: unequal service. This is a societal impact issue, not a reliability or licensing matter."},
  {"id": "3.2-intermediate-07", "course": "csa", "topic": "3.2", "tier": "intermediate", "lo": "3.2.A.1", "prompt": "An airline builds an app that recalculates connecting-flight gate assignments in real time. During development, testers focus heavily on normal weekday traffic but rarely test scenarios involving major storms that delay dozens of flights simultaneously. Which of the following best predicts what will happen when a large storm hits?", "choices": ["The app will perform just as reliably as it does on a normal day, since gate assignment logic does not depend on weather.", "The app's intellectual property protections will fail under storm conditions.", "Because the storm scenario was not adequately tested, the app is at higher risk of failing to perform as expected during exactly the situation when it is needed most.", "The app will automatically become open source so that other airlines can fix it during the storm."], "answer": 2, "explanation": "Testing focused on normal conditions leaves storm-related, high-load scenarios unverified, so the app is at greater risk of failing exactly when accurate gate reassignment matters most. Weather does not affect intellectual property protections or open-source status."},
  {"id": "3.2-intermediate-08", "course": "csa", "topic": "3.2", "tier": "intermediate", "lo": "3.2.A.3", "prompt": "A biology teacher wants to modify a data-visualization program that a former colleague wrote and shared informally as a personal favor, with no license file and no public posting anywhere. The teacher would like to redistribute the modified version to other teachers nationwide through a district curriculum website. What is the most appropriate step?", "choices": ["Redistribute it immediately, since anything shared between colleagues is automatically open source.", "Assume permission was already granted because the original author is a colleague, not a stranger.", "Add a new license to the program without the original author's involvement, since the teacher improved it.", "Contact the original author to clarify how the code may be used and obtain explicit permission before redistributing it widely."], "answer": 3, "explanation": "Because the code was shared informally with no license and no public posting, there is no documented permission to redistribute it widely; contacting the original author is the appropriate way to clarify what is allowed. Informal sharing does not constitute an open-source license."},
  {"id": "3.2-complex-01", "course": "csa", "topic": "3.2", "tier": "complex", "lo": "3.2.A.3", "prompt": "A solo developer builds a medication-reminder app for elderly patients, including a notification-scheduling module copied from an online forum post with no stated license. After launch, users report that reminders occasionally fire hours late, and a pharmacist who volunteers reviewing health apps emails asking whether permission was obtained for the reused code. Which of the following best identifies the most important next steps the developer should take?", "choices": ["Investigate the licensing status of the reused module and separately test the notification-scheduling logic thoroughly to find the cause of the late reminders.", "Remove the entire app from distribution immediately without investigating either issue, since any negative feedback means the app has failed.", "Reply to the pharmacist that health apps are exempt from licensing concerns, and rename the scheduling module to resolve the timing complaints.", "Ignore the licensing question since the code was free to find online, and add a disclaimer instead of investigating the late reminders."], "answer": 0, "explanation": "The two issues, an unclear-license reused module and a reliability problem, are independent and both need direct investigation: checking the module's license and separately testing the scheduling logic. Removing the app outright, claiming a false exemption, or adding a disclaimer instead of investigating all fail to resolve the real underlying problems."},
  {"id": "3.2-complex-02", "course": "csa", "topic": "3.2", "tier": "complex", "lo": "3.2.A.2", "prompt": "A regional bank releases a loan-approval program intended to speed up applications and reduce paperwork for small business owners. Six months later, an audit finds the program approves loans faster for applicants in some zip codes than others, even when their financial profiles are similar, and a local news story raises concerns about unequal access to credit. The bank's leadership considers several responses. Which is the most appropriate first step?", "choices": ["Publicly deny any possibility of unequal impact, since the program was designed with good intentions.", "Investigate whether the program is producing an unintended harmful effect beyond its intended purpose, and adjust or retest the program based on those findings.", "Immediately publish the program's full source code as open source to end the controversy.", "Discontinue the loan-approval process entirely and return to fully manual paperwork with no further evaluation of the software."], "answer": 1, "explanation": "Uneven approval speed across similar applicants is exactly the kind of unintended harmful effect a well-intentioned program can produce, so the appropriate first step is to investigate and address it directly. Denying the problem, publishing all source code, or abandoning the software without investigation are disproportionate responses that skip the necessary diagnostic step."},
  {"id": "3.2-complex-03", "course": "csa", "topic": "3.2", "tier": "complex", "lo": "3.2.A.1", "prompt": "A small startup is building software that controls irrigation valves for a large greenhouse operation, timing water release to the minute. The founders are eager to sign a major client and are debating shortening the testing phase from six weeks to one week, arguing that the core watering logic already \"works fine\" in their demos. An engineer objects. Which of the following best supports the engineer's concern?", "choices": ["Demos already prove reliability under all real-world conditions, so shortening testing carries no risk.", "Shortening the testing phase would primarily create legal exposure rather than reliability concerns.", "Reducing testing time increases the risk that the software will fail under conditions, such as sensor delays, power fluctuations, or extreme weather, that the short demo period never covered.", "Testing time has no bearing on reliability once the core logic compiles without errors."], "answer": 2, "explanation": "Shortening the testing phase removes the opportunity to check behavior under real-world conditions the brief demo never encountered, directly increasing reliability risk. A short demo cannot prove reliability across all conditions, and this concern is about system reliability, not primarily a legal issue."},
  {"id": "3.2-complex-04", "course": "csa", "topic": "3.2", "tier": "complex", "lo": "3.2.A.3", "prompt": "A university research team wants to publish an open-source version of a data-analysis tool they built, which internally relies on a proprietary statistics library that their university licensed for internal use only. A team member suggests several ways to proceed. Which option best resolves the situation?", "choices": ["Publish the entire tool, including the proprietary library's code, as open source, since the team wrote the surrounding program themselves.", "Keep the tool completely private forever, since any use of a proprietary library makes future publication impossible under any circumstance.", "Quietly publish the tool as open source but rename the proprietary library's files so the license violation is harder to detect.", "Replace or remove the proprietary library before publishing, or obtain explicit permission from its owner to redistribute it, so the open-source release does not violate the library's license."], "answer": 3, "explanation": "Because the statistics library is proprietary and licensed only for internal use, publishing the tool as open source requires either removing that dependency or getting explicit permission; anything else risks violating the license. Including the code outright, hiding it, or abandoning the project entirely are inappropriate responses to a solvable problem."},
  {"id": "3.2-complex-05", "course": "csa", "topic": "3.2", "tier": "complex", "lo": "3.2.A.2", "prompt": "An education-technology company releases an adaptive tutoring program that adjusts problem difficulty based on how quickly students answer. Adoption in schools has been strong, and teachers cite improved practice on foundational skills. However, guidance counselors from lower-income districts note that many students only have irregular access to internet-connected devices at home, so the intended benefits are not evenly reaching all students. Which statement best captures this outcome?", "choices": ["The program shows how a tool designed to solve one problem, personalized practice, can still produce an unintended harmful effect, unequal access to its benefits, beyond its original goal.", "The unequal access described has no connection to the impact of the software, since it results from internet infrastructure alone.", "The counselors' observation actually reflects a system-reliability problem within the tutoring program itself.", "The company should immediately release the program's source code as open source to fix the access gap."], "answer": 0, "explanation": "The tutoring software was designed to solve a real problem but its benefits are not reaching all students evenly due to unequal device and internet access, an unintended harmful effect beyond its original goal. This is a societal impact issue, not a reliability defect, and making the code open source would not address unequal internet access."},
  {"id": "3.2-complex-06", "course": "csa", "topic": "3.2", "tier": "complex", "lo": "3.2.A.1", "prompt": "A team builds software for a public library's self-checkout kiosks. Testing was performed extensively using the library's newest barcode scanners, but older kiosks at smaller branch libraries use a different, discontinued scanner model. After rollout, branch staff report frequent freezes only on the older kiosks, and a manager suggests three possible fixes. Which is most likely to actually resolve the underlying issue?", "choices": ["Replacing the checkout software's comments and variable names, since better documentation improves reliability.", "Testing and adjusting the software specifically under the conditions of the older scanner model, since the freezes only occur where testing had not been performed.", "Publishing the software as open source so other libraries can find the bug.", "Purchasing a commercial license for a different barcode-scanning library without first confirming it is compatible with the older kiosks."], "answer": 1, "explanation": "Because testing was performed only on the newer scanners, the freezes on the untested older scanner model point directly to a reliability gap that must be addressed by testing and adjusting the software for that specific hardware. Renaming code elements, publishing the code, or buying an unconfirmed license would not fix the root cause."},
  {"id": "3.2-complex-07", "course": "csa", "topic": "3.2", "tier": "complex", "lo": "3.2.A.2", "prompt": "A wildlife conservation group builds a mobile app, incorporating a species-identification module posted publicly on a research forum under a license that allows free use with attribution, that lets hikers photograph animals to log sightings for population tracking. The app becomes popular far beyond the original research region, and some park rangers report that certain rare species are being disturbed by hikers now actively seeking them out to log a sighting. The group must decide how to respond, including questions about the reused module and the app's real-world effects. Which of the following best identifies the most complete set of appropriate next steps?", "choices": ["Discontinue the app entirely and issue no further communication, since any harmful effect means the project has failed completely.", "Ignore the ranger reports since the app was intended to help conservation, and focus only on confirming the attribution requirement was met.", "Confirm the attribution requirement for the reused module has been properly met, and separately address the unintended harmful effect on rare species by adjusting how the app displays or shares sensitive sighting locations.", "Remove attribution for the module since the app is now popular enough that credit no longer matters, and add a general disclaimer about wildlife disturbance instead of changing the app."], "answer": 2, "explanation": "The situation involves two distinct concerns that both need direct attention: confirming the attribution requirement was met, and separately addressing the unintended harm to rare species caused by the app's popularity. Abandoning the project, ignoring the ecological harm, or removing attribution while only adding a disclaimer all fail to address one or both real issues."},
  {"id": "3.2-complex-08", "course": "csa", "topic": "3.2", "tier": "complex", "lo": "3.2.A.3", "prompt": "A high school robotics team publishes their competition-scoring app for other teams to use for free. The lead programmer had incorporated a path-finding algorithm copied from a stranger's post on a coding forum with no license statement at all, and, separately, the team never tested the app under conditions where multiple robots score at the exact same moment. At a regional tournament, the app both crashes during simultaneous scoring and draws an email from the original forum poster asking how their algorithm ended up in a published app. Which of the following best identifies the most important pair of actions the team should take?", "choices": ["Respond to the forum poster that forum code is always free to use, and add a temporary manual override for scoring without investigating the crash further.", "Assume the crash is unrelated to testing gaps since the app worked fine at practice scrimmages, and avoid replying to the forum poster until after the season ends.", "Rewrite the entire app from scratch in a new programming language, believing this alone resolves both the licensing question and the reliability problem.", "Reach out to the forum poster to clarify the algorithm's licensing and obtain permission if needed, and test the simultaneous-scoring scenario specifically to fix the crash."], "answer": 3, "explanation": "The team faces two separate real problems, unclear licensing on reused code and a reliability failure under an untested condition, and both require direct action: contacting the poster about licensing and specifically testing the scenario that caused the crash. Assuming forum code is free, delaying communication, or rewriting the app in a new language does not, by itself, resolve either issue."},
  {"id": "3.3-basic-01", "course": "csa", "topic": "3.3", "tier": "basic", "lo": "3.3.A.1", "prompt": "Consider the following class.\npublic class Ticket\n{\n    private double price;\n    private String seatNumber;\n}\nWhich statement about access to the instance variables of Ticket is correct?", "choices": ["Both price and seatNumber can be accessed directly from any other class.", "price can be accessed directly from other classes, but seatNumber cannot.", "Neither price nor seatNumber can be accessed directly from another class.", "seatNumber can be accessed directly from other classes, but price cannot."], "answer": 2, "explanation": "Both instance variables are declared private, so the keyword private restricts access to the declaring class only; neither can be accessed directly from outside Ticket. There is no public instance variable in this class, so choices suggesting otherwise are incorrect."},
  {"id": "3.3-basic-02", "course": "csa", "topic": "3.3", "tier": "basic", "lo": "3.3.A.2", "prompt": "A student writes the following class declaration, intending for classes in other files to create Backpack objects.\nclass Backpack\n{\n    private double weight;\n}\nWhich modification follows the convention used in this course for declaring classes?", "choices": ["Change class Backpack to public class Backpack", "Change private double weight; to public double weight;", "Add a public constructor, but leave the class header unchanged", "No modification is needed"], "answer": 0, "explanation": "In this course, classes are always designated public, so the header should read public class Backpack. Making weight public would violate good encapsulation practice, and the class header still needs the public keyword regardless of the constructor."},
  {"id": "3.3-basic-03", "course": "csa", "topic": "3.3", "tier": "basic", "lo": "3.3.A.4", "prompt": "Consider the following class.\npublic class Wallet\n{\n    private double balance;\n}\nTwo Wallet objects are created as follows.\nWallet w1 = new Wallet();\nWallet w2 = new Wallet();\nWhich statement is true about the balance instance variable?", "choices": ["w1 and w2 share a single copy of balance.", "w1 and w2 each have their own separate copy of balance.", "balance does not exist until a method sets it explicitly.", "Only one of the two objects can have a value for balance at a time."], "answer": 1, "explanation": "Instance variables belong to the object, so each Wallet object created has its own independent copy of balance. Changing w1's balance would have no effect on w2's balance."},
  {"id": "3.3-basic-04", "course": "csa", "topic": "3.3", "tier": "basic", "lo": "3.3.A.3", "prompt": "Which of the following constructor headers follows the convention used in this course for declaring constructors? (Assume the class name is Sneaker.)", "choices": ["private Sneaker(double p)", "static Sneaker(double p)", "void Sneaker(double p)", "public Sneaker(double p)"], "answer": 3, "explanation": "In this course, constructors are always designated public. Constructors also never include a return type such as void, and static is not used to declare a constructor."},
  {"id": "3.3-basic-05", "course": "csa", "topic": "3.3", "tier": "basic", "lo": "3.3.A.6", "prompt": "Consider the following class.\npublic class Alarm\n{\n    private boolean isRinging;\n    public void ring()\n    {\n        isRinging = true;\n    }\n    private void reset()\n    {\n        isRinging = false;\n    }\n}\nWhich method can be called from a class other than Alarm?", "choices": ["reset only", "ring only", "both ring and reset", "neither ring nor reset"], "answer": 1, "explanation": "ring is declared public, so it can be accessed both internally and externally to the class. reset is private, so it can only be called from inside the Alarm class."},
  {"id": "3.3-basic-06", "course": "csa", "topic": "3.3", "tier": "basic", "lo": "3.3.A.1", "prompt": "Consider the following class.\npublic class Recipe\n{\n    private int cookTime;\n    public String title;\n}\nThe following statements appear in a class other than Recipe. Assume myRecipe is a properly instantiated Recipe object.\nint t = myRecipe.cookTime;\nString s = myRecipe.title;\nWhat happens when these statements are compiled?", "choices": ["Both statements compile without error.", "Neither statement compiles.", "The second statement compiles, but the first does not.", "The first statement compiles, but the second does not."], "answer": 2, "explanation": "cookTime is private, so myRecipe.cookTime causes a compile-time error outside the class. title is public, so myRecipe.title compiles and can be accessed directly from another class."},
  {"id": "3.3-basic-07", "course": "csa", "topic": "3.3", "tier": "basic", "lo": "3.3.A.5", "prompt": "A class specification for GameScore states that the score attribute should not be directly accessible or modifiable from outside the class. Which declaration correctly follows this specification?", "choices": ["private int score;", "public int score;", "public final score;", "private public int score;"], "answer": 0, "explanation": "Declaring score as private restricts access to the declaring class, satisfying the specification. public int score; would expose the attribute, and the other two options are not valid Java declarations."},
  {"id": "3.3-basic-08", "course": "csa", "topic": "3.3", "tier": "basic", "lo": "3.3.A.2", "prompt": "Which class header follows the convention used in this course?", "choices": ["private class Battery", "class private Battery", "static class Battery", "public class Battery"], "answer": 3, "explanation": "Classes in this course are always designated public and declared with the keyword class, so public class Battery is correct. The other options either place keywords incorrectly or use keywords not used for class headers in this course."},
  {"id": "3.3-basic-09", "course": "csa", "topic": "3.3", "tier": "basic", "lo": "3.3.A.4", "prompt": "Consider the following class.\npublic class Contact\n{\n    private String name;\n    private String phoneNumber;\n}\nWhich statement best describes name and phoneNumber?", "choices": ["They are shared by all Contact objects created from the class.", "They are instance variables, so each Contact object has its own separate copies of them.", "They can be accessed directly from any class once a Contact object is created.", "They must be declared public in order for a Contact object to store values in them."], "answer": 1, "explanation": "name and phoneNumber are instance variables, and each object created from the class has its own independent copy. They remain private and inaccessible from outside the class regardless of whether values have been stored in them."},
  {"id": "3.3-basic-10", "course": "csa", "topic": "3.3", "tier": "basic", "lo": "3.3.A.1", "prompt": "Consider the following class.\npublic class Invoice\n{\n    private double total;\n}\nA class other than Invoice contains the following statement, where myInvoice is a properly instantiated Invoice object.\ndouble amount = myInvoice.total;\nWhat happens when this statement is compiled?", "choices": ["A compile-time error occurs because total is private.", "The statement compiles and amount is assigned the value of total.", "A run-time error occurs because total has not been initialized.", "The statement compiles, but amount is always assigned 0.0."], "answer": 0, "explanation": "Because total is private, it cannot be accessed directly from a class other than Invoice, so the statement fails to compile. This is a compile-time issue, not a run-time one, so no output or default value is ever produced."},
  {"id": "3.3-basic-11", "course": "csa", "topic": "3.3", "tier": "basic", "lo": "3.3.A.6", "prompt": "Consider the following class.\npublic class Router\n{\n    private boolean isConnected;\n    public void connect()\n    {\n        isConnected = true;\n    }\n}\nWhich statement about connect is true?", "choices": ["connect can only be called from inside the Router class.", "connect cannot be called at all because isConnected is private.", "connect can be called both from inside and from outside the Router class.", "connect can only be called from outside the Router class."], "answer": 2, "explanation": "connect is declared public, so it can be accessed both internally and externally to the class. The fact that isConnected is private only restricts direct access to that variable, not calls to the public method that modifies it."},
  {"id": "3.3-basic-12", "course": "csa", "topic": "3.3", "tier": "basic", "lo": "3.3.A.5", "prompt": "A class specification for Locker states that the combination attribute should never be directly accessible from outside the class. Which declaration follows good encapsulation practice as described in this course?", "choices": ["public int combination;", "int combination; public", "public private int combination;", "private int combination;"], "answer": 3, "explanation": "Good encapsulation practice is to designate instance variables as private unless the specification states otherwise, so private int combination; is correct. The other two non-public options are not valid Java syntax."},
  {"id": "3.3-basic-13", "course": "csa", "topic": "3.3", "tier": "basic", "lo": "3.3.A.1", "prompt": "Consider the following class.\npublic class Thermometer\n{\n    public double temperature;\n    private String unit;\n}\nWhich instance variable can be accessed directly from a class other than Thermometer?", "choices": ["temperature only", "unit only", "both temperature and unit", "neither temperature nor unit"], "answer": 0, "explanation": "temperature is declared public, so it can be accessed directly from outside the class. unit is private, restricting its access to the declaring class only."},
  {"id": "3.3-basic-14", "course": "csa", "topic": "3.3", "tier": "basic", "lo": "3.3.A.3", "prompt": "A student wants classes in other files to be able to create Playlist objects. Which constructor declaration should be used?", "choices": ["private Playlist()", "public Playlist()", "void Playlist()", "Playlist private()"], "answer": 1, "explanation": "Constructors in this course are always designated public so that other classes can create objects using them. A private constructor would prevent other classes from instantiating the class, and the other two options are not valid constructor declarations."},
  {"id": "3.3-basic-15", "course": "csa", "topic": "3.3", "tier": "basic", "lo": "3.3.A.6", "prompt": "Consider the following class.\npublic class Elevator\n{\n    private int currentFloor;\n    private void logMovement()\n    {\n        System.out.println(currentFloor);\n    }\n    public void goUp()\n    {\n        currentFloor++;\n        logMovement();\n    }\n}\nWhich statement is true?", "choices": ["logMovement can be called directly from a class other than Elevator.", "goUp cannot call logMovement because logMovement is private.", "goUp can call logMovement because the call happens inside the Elevator class.", "currentFloor must be public for goUp to modify it."], "answer": 2, "explanation": "Private methods can be accessed internally to the class, so goUp calling logMovement from within Elevator is allowed. Private members are only restricted from being accessed externally, and a method never needs its instance variables to be public to modify them from within the same class."},
  {"id": "3.3-intermediate-01", "course": "csa", "topic": "3.3", "tier": "intermediate", "lo": "3.3.A.6", "prompt": "Consider the following class.\npublic class Subscription\n{\n    private double monthlyFee;\n    private boolean active;\n    public Subscription(double fee)\n    {\n        monthlyFee = fee;\n        active = true;\n    }\n    public void cancel()\n    {\n        active = false;\n    }\n    private void logCancellation()\n    {\n        System.out.println(\"Cancelled\");\n    }\n}\nWhich of the following statements, if placed in a class other than Subscription, would compile? Assume sub is a properly instantiated Subscription object.\nI. sub.cancel();\nII. sub.logCancellation();\nIII. double f = sub.monthlyFee;", "choices": ["I and II", "I only", "II and III", "I, II, and III"], "answer": 1, "explanation": "cancel is public, so statement I compiles. logCancellation is private and monthlyFee is private, so statements II and III both cause compile-time errors when accessed from outside the class."},
  {"id": "3.3-intermediate-02", "course": "csa", "topic": "3.3", "tier": "intermediate", "lo": "3.3.A.5", "prompt": "A class specification states that Cart objects should be created by other classes, but the itemCount attribute should never be directly readable or writable from outside the class. Which class declaration meets this specification?\nI.\npublic class Cart\n{\n    public int itemCount;\n    public Cart()\n    {\n        itemCount = 0;\n    }\n}\nII.\nclass Cart\n{\n    private int itemCount;\n    public Cart()\n    {\n        itemCount = 0;\n    }\n}\nIII.\npublic class Cart\n{\n    private int itemCount;\n    public Cart()\n    {\n        itemCount = 0;\n    }\n}", "choices": ["I only", "II only", "I and III", "III only"], "answer": 3, "explanation": "III uses a public class header, as required by convention, with a private itemCount that cannot be accessed directly from outside the class. I fails because itemCount is public, and II fails because the class header omits the required public keyword even though itemCount is private."},
  {"id": "3.3-intermediate-03", "course": "csa", "topic": "3.3", "tier": "intermediate", "lo": "3.3.A.4", "prompt": "Consider the following class.\npublic class BankAccount\n{\n    private double balance;\n    public BankAccount(double startingBalance)\n    {\n        balance = startingBalance;\n    }\n    public double getBalance()\n    {\n        return balance;\n    }\n}\nThe following code appears in another class.\nBankAccount acc1 = new BankAccount(100.0);\nBankAccount acc2 = new BankAccount(250.0);\nSystem.out.println(acc1.getBalance());\nSystem.out.println(acc2.getBalance());\nWhat is printed?", "choices": ["100.0\n250.0", "250.0\n250.0", "100.0\n100.0", "A compile-time error occurs because balance is private."], "answer": 0, "explanation": "Each object has its own copy of the balance instance variable, so acc1 keeps 100.0 and acc2 keeps 250.0. getBalance is public, so calling it from outside the class compiles and works correctly."},
  {"id": "3.3-intermediate-04", "course": "csa", "topic": "3.3", "tier": "intermediate", "lo": "3.3.A.6", "prompt": "Consider the following class.\npublic class Thermostat\n{\n    private double temperature;\n    public Thermostat(double t)\n    {\n        temperature = t;\n    }\n    private boolean isTooHot()\n    {\n        return temperature > 80.0;\n    }\n    public String checkStatus()\n    {\n        if (isTooHot())\n        {\n            return \"hot\";\n        }\n        return \"ok\";\n    }\n}\nWhich statement is true about a class other than Thermostat?", "choices": ["It can call both checkStatus and isTooHot directly.", "It cannot call checkStatus because checkStatus calls a private method.", "It can call checkStatus, which internally calls isTooHot, but it cannot call isTooHot directly.", "It can call isTooHot directly, but not checkStatus."], "answer": 2, "explanation": "checkStatus is public, so it can be called from outside the class, and it may freely call the private method isTooHot from within the class. isTooHot itself cannot be called directly from outside the class because it is private."},
  {"id": "3.3-intermediate-05", "course": "csa", "topic": "3.3", "tier": "intermediate", "lo": "3.3.A.5", "prompt": "Which of the following class declarations best follows the encapsulation conventions used in this course for a Camera class that stores a private resolution value and provides public methods to use it?\nI.\npublic class Camera\n{\n    public int resolution;\n    private Camera(int r)\n    {\n        resolution = r;\n    }\n}\nII.\npublic class Camera\n{\n    private int resolution;\n    public Camera(int r)\n    {\n        resolution = r;\n    }\n    private int getResolution()\n    {\n        return resolution;\n    }\n}\nIII.\npublic class Camera\n{\n    private int resolution;\n    public Camera(int r)\n    {\n        resolution = r;\n    }\n    public int getResolution()\n    {\n        return resolution;\n    }\n}", "choices": ["I only", "II only", "I and II", "III only"], "answer": 3, "explanation": "III has a private instance variable, a public constructor, and a public accessor method, matching the conventions in this course. I incorrectly makes resolution public and the constructor private, and II makes the accessor method private, so no other class could ever retrieve the resolution."},
  {"id": "3.3-intermediate-06", "course": "csa", "topic": "3.3", "tier": "intermediate", "lo": "3.3.A.1", "prompt": "Consider the following class.\npublic class Vehicle\n{\n    private int mileage;\n    public String model;\n    public Vehicle(int m, String mdl)\n    {\n        mileage = m;\n        model = mdl;\n    }\n}\nThe following code appears in another class. Assume car is a properly instantiated Vehicle object.\nString s = car.model;\nint m = car.mileage;\nWhat happens when this code is compiled?", "choices": ["Both lines compile without error.", "The first line compiles, but the second line does not.", "The second line compiles, but the first line does not.", "Neither line compiles."], "answer": 1, "explanation": "model is public, so the first line compiles. mileage is private, so accessing car.mileage directly from outside the class causes a compile-time error on the second line."},
  {"id": "3.3-intermediate-07", "course": "csa", "topic": "3.3", "tier": "intermediate", "lo": "3.3.A.3", "prompt": "A programmer writes the following partial class.\npublic class Order\n{\n    private double total;\n    private Order(double t)\n    {\n        total = t;\n    }\n    public double getTotal()\n    {\n        return total;\n    }\n}\nA class in another file attempts the following statement.\nOrder o = new Order(45.0);\nWhat happens when this statement is compiled?", "choices": ["A compile-time error occurs because the constructor is private.", "The statement compiles and creates a new Order object.", "A compile-time error occurs because total is private.", "The statement compiles, but getTotal cannot be called on o."], "answer": 0, "explanation": "Because the constructor is declared private rather than the required public, it cannot be called from a class other than Order, so new Order(45.0) fails to compile. The private instance variable total is not directly involved in this particular statement."},
  {"id": "3.3-intermediate-08", "course": "csa", "topic": "3.3", "tier": "intermediate", "lo": "3.3.A.5", "prompt": "A class specification for a Password class states that other classes should be able to create Password objects and check whether an entered password matches, but should never be able to read or change the stored value directly. Consider this implementation.\npublic class Password\n{\n    public String value;\n    public Password(String v)\n    {\n        value = v;\n    }\n    public boolean matches(String guess)\n    {\n        return value.equals(guess);\n    }\n}\nWhich change is needed so the class meets the specification?", "choices": ["Change the class header to private class Password", "Change the constructor to private Password(String v)", "Change public String value; to private String value;", "Change matches to return void instead of boolean"], "answer": 2, "explanation": "Making value private prevents other classes from directly reading or changing it, while matches can still access it internally to perform the comparison. The class header and constructor must remain public per course convention, and matches's return type is unrelated to encapsulation of value."},
  {"id": "3.3-intermediate-09", "course": "csa", "topic": "3.3", "tier": "intermediate", "lo": "3.3.A.5", "prompt": "A class specification states that Grade objects should store a private numeric score set only through the constructor, with a public method to retrieve it and no way to modify it afterward. Which implementation satisfies this specification?\nI.\npublic class Grade\n{\n    private double score;\n    public Grade(double s)\n    {\n        score = s;\n    }\n    public void setScore(double s)\n    {\n        score = s;\n    }\n    public double getScore()\n    {\n        return score;\n    }\n}\nII.\npublic class Grade\n{\n    public double score;\n    public Grade(double s)\n    {\n        score = s;\n    }\n}\nIII.\npublic class Grade\n{\n    private double score;\n    public Grade(double s)\n    {\n        score = s;\n    }\n    public double getScore()\n    {\n        return score;\n    }\n}", "choices": ["I only", "II only", "I and III", "III only"], "answer": 3, "explanation": "III sets score only in the constructor, keeps it private, and provides only a public getter, so it cannot be modified after creation. I includes a public setScore method that allows later modification, and II makes score public, allowing direct access and modification from outside the class."},
  {"id": "3.3-intermediate-10", "course": "csa", "topic": "3.3", "tier": "intermediate", "lo": "3.3.A.4", "prompt": "Consider the following class.\npublic class Timer\n{\n    private int seconds;\n    public Timer(int s)\n    {\n        seconds = s;\n    }\n    public void tick()\n    {\n        seconds--;\n    }\n    public int getSeconds()\n    {\n        return seconds;\n    }\n}\nThe following code appears in another class.\nTimer t1 = new Timer(10);\nTimer t2 = new Timer(10);\nt1.tick();\nt1.tick();\nSystem.out.println(t1.getSeconds());\nSystem.out.println(t2.getSeconds());\nWhat is printed?", "choices": ["8\n10", "8\n8", "10\n10", "9\n9"], "answer": 0, "explanation": "t1's seconds is decremented twice to 8, but since each Timer object has its own separate copy of seconds, t2's value remains unchanged at 10."},
  {"id": "3.3-intermediate-11", "course": "csa", "topic": "3.3", "tier": "intermediate", "lo": "3.3.A.6", "prompt": "Consider the following class.\npublic class Printer\n{\n    private int pagesPrinted;\n    public Printer()\n    {\n        pagesPrinted = 0;\n    }\n    private void addPage()\n    {\n        pagesPrinted++;\n    }\n    public void printDocument()\n    {\n        addPage();\n        addPage();\n    }\n    public int getPagesPrinted()\n    {\n        return pagesPrinted;\n    }\n}\nA class in another file creates a Printer object named p and calls p.printDocument(); once. Which statement is true?", "choices": ["The call fails to compile because printDocument calls the private method addPage.", "p.getPagesPrinted() returns 0 because addPage cannot run.", "p.getPagesPrinted() returns 2.", "p.addPage() must also be called directly from the other class for pagesPrinted to update."], "answer": 2, "explanation": "printDocument is public and may call the private method addPage internally, incrementing pagesPrinted twice. There is no need to call addPage directly from outside the class, and doing so would not even compile since addPage is private."},
  {"id": "3.3-intermediate-12", "course": "csa", "topic": "3.3", "tier": "intermediate", "lo": "3.3.A.1", "prompt": "Consider the following class.\npublic class Flight\n{\n    private int flightNumber;\n    private double duration;\n    public String destination;\n    public Flight(int num, double d, String dest)\n    {\n        flightNumber = num;\n        duration = d;\n        destination = dest;\n    }\n}\nThe following statements appear in another class. Assume trip is a properly instantiated Flight object.\nString dest = trip.destination;\ndouble d = trip.duration;\nint num = trip.flightNumber;\nHow many of these three statements compile without error?", "choices": ["0", "1", "2", "3"], "answer": 1, "explanation": "Only destination is public, so only the first statement compiles. duration and flightNumber are both private, so the second and third statements each cause a compile-time error."},
  {"id": "3.3-intermediate-13", "course": "csa", "topic": "3.3", "tier": "intermediate", "lo": "3.3.A.3", "prompt": "Which of the following constructor declarations for a class named HotelRoom follows the convention used in this course, in which classes are created and initialized by code outside the class?", "choices": ["private HotelRoom(int roomNum)\n{\n    number = roomNum;\n}", "void HotelRoom(int roomNum)\n{\n    number = roomNum;\n}", "HotelRoom private(int roomNum)\n{\n    number = roomNum;\n}", "public HotelRoom(int roomNum)\n{\n    number = roomNum;\n}"], "answer": 3, "explanation": "Constructors are always declared public in this course so external classes can create objects. A private constructor would prevent this, void is never used as a constructor return type, and the third option is not valid Java syntax."},
  {"id": "3.3-intermediate-14", "course": "csa", "topic": "3.3", "tier": "intermediate", "lo": "3.3.A.6", "prompt": "Consider the following class.\npublic class Furnace\n{\n    private double temperature;\n    public Furnace(double t)\n    {\n        temperature = t;\n    }\n    private void heat()\n    {\n        temperature++;\n    }\n    public void run()\n    {\n        heat();\n        heat();\n        heat();\n    }\n}\nA class in another file creates a Furnace object f with temperature 60.0 and calls f.run(); once. Which of the following is true?", "choices": ["temperature becomes 63.0 because run calls heat three times.", "The call to f.run() fails to compile because heat is private.", "temperature remains 60.0 because heat cannot modify a private variable.", "temperature becomes 61.0 because only the first call to heat succeeds."], "answer": 0, "explanation": "run is public and calls the private method heat three times from within the class, which is allowed. Each call increments temperature by one, resulting in 63.0; a private method can freely modify a private instance variable of its own class."},
  {"id": "3.3-intermediate-15", "course": "csa", "topic": "3.3", "tier": "intermediate", "lo": "3.3.A.5", "prompt": "A class specification states that an Email class should let other classes create Email objects with a subject and body, and read the subject through a public method, but never modify either attribute after creation. Consider these two candidates.\nI.\npublic class Email\n{\n    private String subject;\n    private String body;\n    public Email(String s, String b)\n    {\n        subject = s;\n        body = b;\n    }\n    public String getSubject()\n    {\n        return subject;\n    }\n    public void setSubject(String s)\n    {\n        subject = s;\n    }\n}\nII.\npublic class Email\n{\n    private String subject;\n    private String body;\n    public Email(String s, String b)\n    {\n        subject = s;\n        body = b;\n    }\n    public String getSubject()\n    {\n        return subject;\n    }\n}\nWhich candidate meets the specification?", "choices": ["I only", "Neither I nor II", "II only", "Both I and II"], "answer": 2, "explanation": "II keeps subject and body private, initializes them only in the constructor, and offers only a public getter, so subject can never be modified after creation. I includes a public setSubject method, which allows external modification and violates the specification."},
  {"id": "3.3-complex-01", "course": "csa", "topic": "3.3", "tier": "complex", "lo": "3.3.A.1", "prompt": "A student writes the following class intending for it to store a private inventory count that can only be changed through public methods restockItem and sellItem.\npublic class InventoryItem\n{\n    private int count;\n    private String name;\n    public InventoryItem(String n, int c)\n    {\n        name = n;\n        count = c;\n    }\n    public void restockItem(int amount)\n    {\n        count = count + amount;\n    }\n    public void sellItem(int amount)\n    {\n        count = count - amount;\n    }\n    public int getCount()\n    {\n        return count;\n    }\n}\nA class in another file contains the following code, where item is a properly instantiated InventoryItem object.\nitem.restockItem(5);\nint c = item.count;\nWhat happens when this code is compiled?", "choices": ["Both lines compile because count is used consistently within the class.", "Neither line compiles because InventoryItem has no default constructor.", "The first line fails to compile because restockItem is private.", "The first line compiles, but the second line fails to compile because count is private."], "answer": 3, "explanation": "restockItem is public, so calling it from another class compiles. The second line directly accesses item.count from outside the class, but count is private, so that line fails to compile; the class should instead call the public getCount method."},
  {"id": "3.3-complex-02", "course": "csa", "topic": "3.3", "tier": "complex", "lo": "3.3.A.5", "prompt": "A class specification states that a StudentRecord class should allow other classes to create StudentRecord objects with a name and gpa, read the gpa through a public method, but never read or directly modify either attribute in any other way. Consider the following five candidate declarations.\nI.\npublic class StudentRecord\n{\n    public String name;\n    public double gpa;\n    public StudentRecord(String n, double g)\n    {\n        name = n;\n        gpa = g;\n    }\n}\nII.\npublic class StudentRecord\n{\n    private String name;\n    private double gpa;\n    public StudentRecord(String n, double g)\n    {\n        name = n;\n        gpa = g;\n    }\n    public double getGpa()\n    {\n        return gpa;\n    }\n}\nIII.\nclass StudentRecord\n{\n    private String name;\n    private double gpa;\n    public StudentRecord(String n, double g)\n    {\n        name = n;\n        gpa = g;\n    }\n    public double getGpa()\n    {\n        return gpa;\n    }\n}\nIV.\npublic class StudentRecord\n{\n    private String name;\n    public double gpa;\n    public StudentRecord(String n, double g)\n    {\n        name = n;\n        gpa = g;\n    }\n    public double getGpa()\n    {\n        return gpa;\n    }\n}\nV.\npublic class StudentRecord\n{\n    private String name;\n    private double gpa;\n    private StudentRecord(String n, double g)\n    {\n        name = n;\n        gpa = g;\n    }\n    public double getGpa()\n    {\n        return gpa;\n    }\n}\nWhich candidate meets the specification?", "choices": ["I", "II", "III", "IV"], "answer": 1, "explanation": "II uses a public class header as required by convention, keeps both name and gpa private, and provides only a public getter for gpa. I makes both variables public, III omits the required public class header, IV leaves gpa public, and V makes the constructor private, which would prevent other classes from ever creating a StudentRecord."},
  {"id": "3.3-complex-03", "course": "csa", "topic": "3.3", "tier": "complex", "lo": "3.3.A.6", "prompt": "Consider the following class.\npublic class Robot\n{\n    private int xPosition;\n    private int yPosition;\n    public Robot(int x, int y)\n    {\n        xPosition = x;\n        yPosition = y;\n    }\n    private void moveX(int dx)\n    {\n        xPosition = xPosition + dx;\n    }\n    private void moveY(int dy)\n    {\n        yPosition = yPosition + dy;\n    }\n    public void moveDiagonally(int dx, int dy)\n    {\n        moveX(dx);\n        moveY(dy);\n    }\n    public int getX()\n    {\n        return xPosition;\n    }\n    public int getY()\n    {\n        return yPosition;\n    }\n}\nA class in another file creates a Robot object r with position (0, 0) and executes the following.\nr.moveDiagonally(3, 4);\nSystem.out.println(r.getX());\nSystem.out.println(r.getY());\nWhat is printed?", "choices": ["A compile-time error occurs because moveDiagonally calls the private methods moveX and moveY.", "0\n0", "3\n4", "4\n3"], "answer": 2, "explanation": "moveDiagonally is public and is allowed to call the private methods moveX and moveY internally. Those calls update xPosition to 3 and yPosition to 4, which getX and getY then correctly report."},
  {"id": "3.3-complex-04", "course": "csa", "topic": "3.3", "tier": "complex", "lo": "3.3.A.6", "prompt": "A class specification for a Vault class states that other classes should be able to create Vault objects and attempt to unlock them by supplying a code, receiving true or false, but should never be able to read the stored code or call any internal helper logic directly. Consider this implementation.\npublic class Vault\n{\n    private String secretCode;\n    public Vault(String code)\n    {\n        secretCode = code;\n    }\n    private boolean codesMatch(String attempt)\n    {\n        return secretCode.equals(attempt);\n    }\n    public boolean unlock(String attempt)\n    {\n        return codesMatch(attempt);\n    }\n}\nWhich statement about this implementation is correct?", "choices": ["It meets the specification: unlock is the only member callable from outside, and it can still use codesMatch internally.", "It fails the specification because unlock cannot call the private method codesMatch.", "It fails the specification because secretCode should be public so unlock can compare it.", "It fails the specification because private methods cannot be called from a public constructor."], "answer": 0, "explanation": "unlock is the only public member, satisfying the specification that outside classes may only attempt an unlock, and public methods are always free to call private methods declared in the same class. secretCode correctly remains private, since unlock accesses it internally through codesMatch without exposing it externally."},
  {"id": "3.3-complex-05", "course": "csa", "topic": "3.3", "tier": "complex", "lo": "3.3.A.5", "prompt": "A student's PaymentCard class does not compile.\npublic class PaymentCard\n{\n    private double balance;\n    private String cardNumber;\n    public PaymentCard(double b, String num)\n    {\n        balance = b;\n        cardNumber = num;\n    }\n    public boolean charge(double amount)\n    {\n        if (amount <= balance)\n        {\n            balance = balance - amount;\n            return true;\n        }\n        return false;\n    }\n}\nIn a class other than PaymentCard, the student writes the following code.\nPaymentCard card = new PaymentCard(100.0, \"1234\");\nif (card.charge(30.0))\n{\n    System.out.println(card.balance);\n}\nWhich change should be made so the code compiles while preserving encapsulation of the card's data?", "choices": ["Remove the constructor parameters so PaymentCard() takes no arguments.", "Change balance to public double balance;", "Change charge to private boolean charge(double amount)", "Add a public method such as getBalance that returns balance, and call card.getBalance() instead of card.balance"], "answer": 3, "explanation": "Adding a public accessor method preserves encapsulation while giving outside code a legitimate way to read balance. Making balance public would fix the compile error but break encapsulation, and the other two changes do not address the actual problem, which is the direct access to the private field card.balance."},
  {"id": "3.3-complex-06", "course": "csa", "topic": "3.3", "tier": "complex", "lo": "3.3.A.6", "prompt": "Consider the following class.\npublic class ScoreTracker\n{\n    private int points;\n    private int bonusRounds;\n    public ScoreTracker(int startingPoints)\n    {\n        points = startingPoints;\n        bonusRounds = 0;\n    }\n    private void applyBonus()\n    {\n        points = points + 10;\n        bonusRounds++;\n    }\n    public void playRound(boolean earnedBonus)\n    {\n        points++;\n        if (earnedBonus)\n        {\n            applyBonus();\n        }\n    }\n    public int getPoints()\n    {\n        return points;\n    }\n}\nA class in another file creates a ScoreTracker object s with startingPoints 0, then executes the following.\ns.playRound(false);\ns.playRound(true);\ns.playRound(true);\nSystem.out.println(s.getPoints());\nWhat is printed?", "choices": ["3", "23", "20", "A compile-time error occurs because playRound calls the private method applyBonus."], "answer": 1, "explanation": "The first call increments points to 1. Each of the next two calls increments points by 1 and then calls the private method applyBonus, which is allowed since the call happens inside the class, adding 10 each time: 1 to 2 to 12 to 13 to 23. playRound is public, so all three calls compile and run successfully."},
  {"id": "3.3-complex-07", "course": "csa", "topic": "3.3", "tier": "complex", "lo": "3.3.A.1", "prompt": "Consider the following two classes.\npublic class Coordinate\n{\n    private double xValue;\n    private double yValue;\n    public Coordinate(double x, double y)\n    {\n        xValue = x;\n        yValue = y;\n    }\n    public double getX()\n    {\n        return xValue;\n    }\n    public double getY()\n    {\n        return yValue;\n    }\n}\npublic class Mapper\n{\n    public double totalDistance(Coordinate a, Coordinate b)\n    {\n        double dx = a.xValue - b.xValue;\n        double dy = a.yValue - b.yValue;\n        return dx + dy;\n    }\n}\nWhy does the Mapper class fail to compile?", "choices": ["Coordinate objects cannot be passed as method parameters.", "totalDistance must be declared private because it uses two objects.", "The Coordinate constructor was never called inside Mapper.", "totalDistance directly accesses xValue and yValue, which are private instance variables of Coordinate, from outside the Coordinate class."], "answer": 3, "explanation": "Because xValue and yValue are private, they can only be accessed inside the declaring class, Coordinate. Mapper is a different class, so a.xValue and b.xValue cause compile-time errors; Mapper should instead call the public getX and getY methods."},
  {"id": "3.3-complex-08", "course": "csa", "topic": "3.3", "tier": "complex", "lo": "3.3.A.5", "prompt": "A class specification states that a Membership class should have a public class header, a private id attribute set only via the constructor, and a public method isActive that other classes can call, with no other public members. Which candidate meets this specification?\nI.\npublic class Membership\n{\n    private String id;\n    private boolean active;\n    public Membership(String memberId)\n    {\n        id = memberId;\n        active = true;\n    }\n    public boolean isActive()\n    {\n        return active;\n    }\n    public String id;\n}\nII.\npublic class Membership\n{\n    private String id;\n    private boolean active;\n    private Membership(String memberId)\n    {\n        id = memberId;\n        active = true;\n    }\n    public boolean isActive()\n    {\n        return active;\n    }\n}\nIII.\npublic class Membership\n{\n    private String id;\n    private boolean active;\n    public Membership(String memberId)\n    {\n        id = memberId;\n        active = true;\n    }\n    public boolean isActive()\n    {\n        return active;\n    }\n}", "choices": ["I only", "II only", "III only", "I and III"], "answer": 2, "explanation": "III correctly uses a public class header, a private id, a public constructor, and only isActive as an additional public member. I is invalid because it declares id twice, once private and once public, and II makes the constructor private, which would prevent other classes from ever creating a Membership object."},
  {"id": "3.3-complex-09", "course": "csa", "topic": "3.3", "tier": "complex", "lo": "3.3.A.6", "prompt": "Consider the following class.\npublic class TemperatureLog\n{\n    private double reading;\n    public TemperatureLog(double r)\n    {\n        reading = clamp(r);\n    }\n    private double clamp(double value)\n    {\n        if (value > 120.0)\n        {\n            return 120.0;\n        }\n        return value;\n    }\n    public double getReading()\n    {\n        return reading;\n    }\n}\nA class in another file executes the following.\nTemperatureLog log = new TemperatureLog(150.0);\nSystem.out.println(log.getReading());\nWhat is printed?", "choices": ["150.0", "120.0", "A compile-time error occurs because the constructor calls the private method clamp.", "0.0"], "answer": 1, "explanation": "The public constructor is allowed to call the private method clamp from within the class, which caps the passed-in value of 150.0 down to 120.0 before storing it in reading. getReading is public and simply returns this stored value."},
  {"id": "3.3-complex-10", "course": "csa", "topic": "3.3", "tier": "complex", "lo": "3.3.A.1", "prompt": "Consider the following class.\npublic class Library\n{\n    private int totalBooks;\n    private boolean isOpen;\n    public String branchName;\n    public Library(String name, int books)\n    {\n        branchName = name;\n        totalBooks = books;\n        isOpen = false;\n    }\n    public void open()\n    {\n        isOpen = true;\n    }\n    private void restock(int amount)\n    {\n        totalBooks = totalBooks + amount;\n    }\n}\nThe following statements appear in another class. Assume lib is a properly instantiated Library object.\nlib.open();\nString b = lib.branchName;\nlib.restock(5);\nint t = lib.totalBooks;\nboolean open = lib.isOpen;\nHow many of these five statements compile without error?", "choices": ["2", "3", "4", "5"], "answer": 0, "explanation": "Only lib.open() and String b = lib.branchName; compile, because open and branchName are public. lib.restock(5) fails since restock is private, and lib.totalBooks and lib.isOpen both fail since totalBooks and isOpen are private instance variables."},
  {"id": "3.3-complex-11", "course": "csa", "topic": "3.3", "tier": "complex", "lo": "3.3.A.5", "prompt": "A programmer's Playlist class does not properly restrict access. Other classes should be able to create Playlist objects, add songs by increasing songCount through a public method, and read songCount, but never set songCount directly to an arbitrary value.\npublic class Playlist\n{\n    public int songCount;\n    public Playlist()\n    {\n        songCount = 0;\n    }\n    public void addSong()\n    {\n        songCount++;\n    }\n}\nWhich change best fixes the encapsulation of this class while keeping addSong and a way to read songCount from outside the class?", "choices": ["Delete the constructor entirely.", "Change addSong to private void addSong()", "Change the class header to private class Playlist", "Change public int songCount; to private int songCount; and add a public method such as getSongCount that returns songCount"], "answer": 3, "explanation": "Making songCount private prevents other classes from setting it directly, while adding a public getSongCount method still allows other classes to read its value. Making addSong private would prevent other classes from ever adding a song, and the class header must remain public per course convention."},
  {"id": "3.3-complex-12", "course": "csa", "topic": "3.3", "tier": "complex", "lo": "3.3.A.6", "prompt": "Consider the following class.\npublic class Battery\n{\n    private int chargeLevel;\n    public Battery(int startLevel)\n    {\n        chargeLevel = startLevel;\n    }\n    private void adjust(int amount)\n    {\n        chargeLevel = chargeLevel + amount;\n        if (chargeLevel > 100)\n        {\n            chargeLevel = 100;\n        }\n    }\n    public void charge(int amount)\n    {\n        adjust(amount);\n    }\n    public void drain(int amount)\n    {\n        adjust(-amount);\n    }\n    public int getChargeLevel()\n    {\n        return chargeLevel;\n    }\n}\nA class in another file creates two Battery objects.\nBattery b1 = new Battery(90);\nBattery b2 = new Battery(90);\nb1.charge(20);\nb2.drain(30);\nSystem.out.println(b1.getChargeLevel());\nSystem.out.println(b2.getChargeLevel());\nWhat is printed?", "choices": ["100\n100", "110\n60", "100\n60", "90\n90"], "answer": 2, "explanation": "charge and drain are public methods that both call the private method adjust internally. b1's charge(20) raises chargeLevel to 110, which adjust clamps to 100; b2's drain(30) lowers chargeLevel to 60, which is not above 100, so it is left unclamped. Since each object has its own copy of chargeLevel, b1 and b2 are updated independently."},
  {"id": "3.3-complex-13", "course": "csa", "topic": "3.3", "tier": "complex", "lo": "3.3.A.5", "prompt": "A class specification requires a ContactCard class with a public class header, private name and private phoneNumber attributes set only via constructor, and a public method fullInfo that returns a combined String, with no accessor methods for the individual fields. Which candidate meets this specification?\nI.\npublic class ContactCard\n{\n    private String name;\n    private String phoneNumber;\n    public ContactCard(String n, String p)\n    {\n        name = n;\n        phoneNumber = p;\n    }\n    public String fullInfo()\n    {\n        return name + \" \" + phoneNumber;\n    }\n    public String getName()\n    {\n        return name;\n    }\n}\nII.\npublic class ContactCard\n{\n    private String name;\n    private String phoneNumber;\n    public ContactCard(String n, String p)\n    {\n        name = n;\n        phoneNumber = p;\n    }\n    public String fullInfo()\n    {\n        return name + \" \" + phoneNumber;\n    }\n}\nIII.\npublic class ContactCard\n{\n    public String name;\n    public String phoneNumber;\n    public ContactCard(String n, String p)\n    {\n        name = n;\n        phoneNumber = p;\n    }\n    public String fullInfo()\n    {\n        return name + \" \" + phoneNumber;\n    }\n}\nWhich candidate meets the specification?", "choices": ["I only", "II only", "III only", "I and II"], "answer": 1, "explanation": "II keeps both attributes private, sets them only through the constructor, and exposes only the required fullInfo method. I adds an extra public getName accessor that the specification says should not exist, and III makes both attributes public, allowing direct external access and modification."},
  {"id": "3.3-complex-14", "course": "csa", "topic": "3.3", "tier": "complex", "lo": "3.3.A.1", "prompt": "Consider the following class.\npublic class Coin\n{\n    private int value;\n    public Coin(int v)\n    {\n        value = v;\n    }\n    public boolean isWorthMoreThan(Coin other)\n    {\n        return value > other.value;\n    }\n}\nA class other than Coin executes the following.\nCoin c1 = new Coin(25);\nCoin c2 = new Coin(10);\nSystem.out.println(c1.isWorthMoreThan(c2));\nWhat happens when this code is compiled and run?", "choices": ["A compile-time error occurs because isWorthMoreThan accesses other.value, and value is private.", "A compile-time error occurs because Coin objects cannot be passed as method parameters.", "false is printed because private variables cannot be compared.", "true is printed, because code inside the Coin class may access the private value field of any Coin object, including other."], "answer": 3, "explanation": "The keyword private restricts access to the declaring class, not to a single instance, so code written inside Coin can access the private value field of any Coin object, including the other parameter. Since c1's value (25) is greater than c2's value (10), isWorthMoreThan returns and prints true."},
  {"id": "3.3-complex-15", "course": "csa", "topic": "3.3", "tier": "complex", "lo": "3.3.A.1", "prompt": "A programmer explains their Odometer class design to a classmate: instance variables are private so that no other class can change them without going through the class's own methods, and the constructor and all methods that other classes need to call are public. Which statement best evaluates this design philosophy in terms of encapsulation?", "choices": ["It correctly reflects encapsulation: hiding implementation details behind private data and exposing only necessary public members.", "It is incorrect because encapsulation requires all instance variables to be public so any class can verify their values.", "It is incorrect because private instance variables can never be read by any method, even those inside the class.", "It is incorrect because constructors must always be private to protect object creation."], "answer": 0, "explanation": "This design matches the definition of data encapsulation used in this course: implementation details, such as private instance variables, are hidden from external classes, while public constructors and methods provide the only access points. Instance variables being public would break encapsulation, private members remain fully accessible within their own class, and constructors in this course are always public, not private."},
  {"id": "3.4-basic-01", "course": "csa", "topic": "3.4", "tier": "basic", "lo": "3.4.A.2", "prompt": "Consider the following class.\npublic class Coin\n{\n    private boolean heads;\n    public Coin(boolean startHeads)\n    {\n        heads = startHeads;\n    }\n}\nWhich of the following correctly creates a Coin object representing heads?", "choices": ["Coin c = new Coin(true);", "Coin c = Coin(true);", "Coin c = new Coin();", "boolean c = new Coin(true);"], "answer": 0, "explanation": "The constructor requires the keyword new followed by a matching boolean argument, as in choice A. Choice B omits new, which is required to allocate and construct the object. Choice C supplies no argument, but the class has no no-argument constructor since one constructor was already written. Choice D declares c as type boolean instead of type Coin."},
  {"id": "3.4-basic-02", "course": "csa", "topic": "3.4", "tier": "basic", "lo": "3.4.A.4", "prompt": "The following class does not include a constructor.\npublic class Ticket\n{\n    private int seatNumber;\n    private String section;\n}\nWhich statement about creating a Ticket object is true?", "choices": ["A Ticket object cannot be created because no constructor was written.", "Java automatically supplies a no-argument constructor that sets seatNumber to 0 and section to null.", "Java automatically supplies a no-argument constructor that sets seatNumber to 0 and section to an empty string \"\".", "The code will not compile until a constructor is added manually."], "answer": 1, "explanation": "When a class has no explicit constructor, Java provides a default no-argument constructor that sets each instance variable to its type's default value: 0 for int and null for any reference type, including String. Choice C is tempting but incorrect because String, as a reference type, defaults to null, not an empty string."},
  {"id": "3.4-basic-03", "course": "csa", "topic": "3.4", "tier": "basic", "lo": "3.4.A.5", "prompt": "public class Counter\n{\n    private int count;\n    public Counter()\n    {\n    }\n}\nCounter c = new Counter();\nWhat is the value of count immediately after this code executes?", "choices": ["0", "1", "-1", "The value is undefined until explicitly set"], "answer": 0, "explanation": "Even though the constructor body is empty, count is still initialized because Java assigns every uninitialized int instance variable the default value 0. Choice D is incorrect because Java always guarantees a default value; it is never left undefined."},
  {"id": "3.4-basic-04", "course": "csa", "topic": "3.4", "tier": "basic", "lo": "3.4.A.5", "prompt": "public class Thermometer\n{\n    private double reading;\n    public Thermometer()\n    {\n    }\n}\nThermometer t = new Thermometer();\nWhat is the value of reading immediately after this code executes?", "choices": ["0", "0.0", "null", "undefined"], "answer": 1, "explanation": "The default value for a double instance variable is 0.0. Choice A, 0, is the default for int, not double, so it does not precisely describe a double value."},
  {"id": "3.4-basic-05", "course": "csa", "topic": "3.4", "tier": "basic", "lo": "3.4.A.5", "prompt": "public class Light\n{\n    private boolean isOn;\n    public Light()\n    {\n    }\n}\nLight lamp = new Light();\nSystem.out.println(lamp.isOnStatus());\nAssume isOnStatus() simply returns isOn. What is printed?", "choices": ["true", "false", "0", "null"], "answer": 1, "explanation": "The default value for a boolean instance variable is false, so an empty constructor leaves isOn as false. There is no reason for it to default to true."},
  {"id": "3.4-basic-06", "course": "csa", "topic": "3.4", "tier": "basic", "lo": "3.4.A.5", "prompt": "public class Book\n{\n    private String title;\n    public Book()\n    {\n    }\n}\nBook b = new Book();\nWhat is the value of title immediately after this code executes?", "choices": ["null", "\"\" (an empty string)", "0", "\"null\" (a four-character string)"], "answer": 0, "explanation": "String is a reference type, so its default value is the null reference, not an empty string or the four-character text \"null\". Choice B is a common misconception; Java does not initialize String fields to empty strings automatically."},
  {"id": "3.4-basic-07", "course": "csa", "topic": "3.4", "tier": "basic", "lo": "3.4.A.1", "prompt": "A Backpack object has a private int itemCount and a private double totalWeight as its instance variables. This best illustrates which kind of relationship between the Backpack class and its instance variables?", "choices": ["is-a", "extends", "uses-a", "has-a"], "answer": 3, "explanation": "An object's instance variables represent attributes that belong to it, which is described as a has-a relationship: a Backpack has an itemCount and has a totalWeight. is-a and extends describe inheritance relationships between classes, which are not part of this scenario."},
  {"id": "3.4-basic-08", "course": "csa", "topic": "3.4", "tier": "basic", "lo": "3.4.A.2", "prompt": "What is the primary purpose of a constructor in a Java class?", "choices": ["To destroy an object when it is no longer needed", "To compare two objects for equality", "To set the initial state of an object when it is created", "To return a value computed from the object's instance variables"], "answer": 2, "explanation": "A constructor's job is to set up the initial state of a newly created object, typically by assigning values to its instance variables. Constructors do not return values (not even void), destroy objects, or compare objects."},
  {"id": "3.4-basic-09", "course": "csa", "topic": "3.4", "tier": "basic", "lo": "3.4.A.2", "prompt": "public class Rectangle\n{\n    private int width;\n    private int height;\n    public Rectangle(int rectWidth, int rectHeight)\n    {\n        width = rectWidth;\n        height = rectHeight;\n    }\n}\nWhich of the following correctly creates a Rectangle object with width 4 and height 9?", "choices": ["Rectangle r = new Rectangle(9, 4, 0);", "Rectangle r = Rectangle(4, 9);", "Rectangle r = new Rectangle(4, 9);", "Rectangle r = new Rectangle(\"4\", \"9\");"], "answer": 2, "explanation": "The constructor takes exactly two int arguments in the order width, then height, so new Rectangle(4, 9) is correct. The other choices use the wrong number of arguments, omit new, or pass String literals instead of int values."},
  {"id": "3.4-basic-10", "course": "csa", "topic": "3.4", "tier": "basic", "lo": "3.4.A.4", "prompt": "public class Robot\n{\n    private String name;\n    private int batteryLevel;\n    public Robot()\n    {\n    }\n}\nRobot r = new Robot();\nSystem.out.println(r.getName() + \" \" + r.getBatteryLevel());\nAssume the getters simply return the instance variables. What is printed?", "choices": ["It causes a compile-time error", "It causes a NullPointerException at runtime", "Robot 100", "null 0"], "answer": 3, "explanation": "With no explicit constructor, Java's default no-argument constructor sets name (a reference type) to null and batteryLevel (an int) to 0, so \"null 0\" is printed. There is no error because accessing a null String field, without calling a method on it, is safe."},
  {"id": "3.4-basic-11", "course": "csa", "topic": "3.4", "tier": "basic", "lo": "3.4.A.2", "prompt": "A class Point has instance variables private int x and private int y. Which of the following is a correct constructor for this class?", "choices": ["public Point(int a, int b)\n{\n    x = a;\n    y = b;\n}", "public void Point(int a, int b)\n{\n    x = a;\n    y = b;\n}", "public Point(int a, int b)\n{\n    a = x;\n    b = y;\n}", "private Point(int a, int b)\n{\n    x = a;\n    y = b;\n}"], "answer": 0, "explanation": "Choice A correctly assigns each parameter to its matching instance variable using a public constructor with no return type. Choice B incorrectly adds a void return type, which makes it a regular method rather than a constructor. Choice C assigns in the reverse direction, leaving x and y unset. Choice D uses private, which prevents the object from being constructed from outside the class."},
  {"id": "3.4-basic-12", "course": "csa", "topic": "3.4", "tier": "basic", "lo": "3.4.A.4", "prompt": "A programmer writes a class with only private instance variables and no constructor. What happens when this class is compiled and an object is created with a no-argument call?", "choices": ["It compiles but no objects of the class can ever be created.", "It fails to compile because every class must have an explicit constructor.", "It compiles successfully, and Java provides a default no-argument constructor.", "It compiles only if all instance variables are declared public."], "answer": 2, "explanation": "Java automatically supplies a no-argument default constructor whenever a class defines no constructors of its own, so the class compiles and objects can be created normally. A class is never required to declare an explicit constructor, and instance variable visibility does not affect whether a default constructor is generated."},
  {"id": "3.4-basic-13", "course": "csa", "topic": "3.4", "tier": "basic", "lo": "3.4.A.5", "prompt": "public class GameStats\n{\n    private int wins;\n    private boolean gameOver;\n    public GameStats()\n    {\n    }\n}\nGameStats stats = new GameStats();\nSystem.out.println(stats.getWins() + \" \" + stats.isGameOver());\nAssume the accessor methods simply return the instance variables. What is printed?", "choices": ["It causes a compile-time error", "\"1 false\"", "\"0 true\"", "\"0 false\""], "answer": 3, "explanation": "With an empty constructor body, wins keeps its default int value of 0 and gameOver keeps its default boolean value of false, so \"0 false\" is printed. Neither field is ever set to a nonzero or true value in this class."},
  {"id": "3.4-basic-14", "course": "csa", "topic": "3.4", "tier": "basic", "lo": "3.4.A.2", "prompt": "Which statement about constructors is correct?", "choices": ["Constructors must specify a return type of void.", "Constructors must return an int representing success.", "Constructors have the same name as the class and specify no return type.", "Constructors are an optional keyword added before any method header."], "answer": 2, "explanation": "A constructor is a special method-like member that shares its name with the class and has no return type at all, not even void. Choices A and B incorrectly assume constructors return something, and choice D confuses constructors with a keyword rather than a distinct kind of class member."},
  {"id": "3.4-basic-15", "course": "csa", "topic": "3.4", "tier": "basic", "lo": "3.4.A.1", "prompt": "Two separate Coin objects are each created using new Coin(true), based on the Coin class shown earlier in this set. Which best describes these two objects?", "choices": ["They are the same object because they have identical instance variable values.", "They are different objects with different states because each occupies different memory.", "They cannot both have heads equal to true.", "They are different objects, but they currently have the same state, since state is defined by the values of instance variables."], "answer": 3, "explanation": "Object state is defined by the values of an object's instance variables at a given time, not by whether the objects are the same object in memory. Two distinct Coin objects can independently hold identical instance variable values, meaning they have the same state while remaining two separate objects."},
  {"id": "3.4-intermediate-01", "course": "csa", "topic": "3.4", "tier": "intermediate", "lo": "3.4.A.2", "prompt": "public class Player\n{\n    private String name;\n    private int score;\n    public Player(String playerName, int playerScore)\n    {\n        name = playerName;\n        playerScore = score;\n    }\n}\nPlayer p = new Player(\"Ari\", 50);\nWhat is the state of p immediately after this code executes?", "choices": ["name is \"Ari\" and score is 0", "name is \"Ari\" and score is 50", "name is null and score is 50", "The code does not compile"], "answer": 0, "explanation": "The line playerScore = score assigns the instance variable's default value (0) to the parameter, rather than assigning the parameter to the instance variable, so score never changes from its default value of 0. The name field is assigned correctly, since name = playerName follows the correct direction."},
  {"id": "3.4-intermediate-02", "course": "csa", "topic": "3.4", "tier": "intermediate", "lo": "3.4.A.2", "prompt": "A class Recipe has instance variables private String title and private int servings. A programmer wants to create an object using the call Recipe r = new Recipe(\"Chili\", 6);\nWhich constructor correctly compiles for this call and sets both instance variables to the argument values?", "choices": ["public Recipe(String title, int servings)\n{\n    title = title;\n    servings = servings;\n}", "public Recipe(String recipeTitle, int recipeServings)\n{\n    title = recipeTitle;\n    servings = recipeServings;\n}", "public Recipe(String recipeTitle, int recipeServings)\n{\n    recipeTitle = title;\n    recipeServings = servings;\n}", "public Recipe(int servings, String title)\n{\n    title = title;\n    servings = servings;\n}"], "answer": 1, "explanation": "Choice B uses distinct parameter names and assigns each parameter to its matching instance variable, correctly compiling for the call and setting both fields. Choice A uses the same names for the parameters and instance variables, so title = title and servings = servings only assign each parameter to itself, leaving the instance variables at their default values. Choice C assigns in the wrong direction. Choice D reverses the parameter types, so it does not match the call's argument order and fails to compile."},
  {"id": "3.4-intermediate-03", "course": "csa", "topic": "3.4", "tier": "intermediate", "lo": "3.4.A.4", "prompt": "public class Box\n{\n    private double length;\n    private double width;\n    private double height;\n    public Box(double side)\n    {\n        length = side;\n        width = side;\n        height = side;\n    }\n    public Box(double boxLength, double boxWidth, double boxHeight)\n    {\n        length = boxLength;\n        width = boxWidth;\n        height = boxHeight;\n    }\n}\nGiven the two constructors above, which of the following object creations is valid?", "choices": ["Box b = new Box(2.0, 3.0);", "Box b = new Box();", "Box b = new Box(4.0, 5.0, 6.0);", "Box b = new Box(4.0, 5.0, 6.0, 7.0);"], "answer": 2, "explanation": "The three-argument call matches the second constructor exactly. There is no two-argument or four-argument constructor, so choices A and D fail to compile. There is also no no-argument constructor, since writing any explicit constructor prevents Java from generating its usual default no-argument constructor, so choice B fails to compile as well."},
  {"id": "3.4-intermediate-04", "course": "csa", "topic": "3.4", "tier": "intermediate", "lo": "3.4.A.2", "prompt": "public class Membership\n{\n    private boolean active;\n    private String level;\n    public Membership(boolean isActive, String memberLevel)\n    {\n        level = memberLevel;\n        isActive = active;\n    }\n}\nMembership m = new Membership(true, \"Gold\");\nSystem.out.println(m.getLevel() + \" \" + m.isActiveStatus());\nAssume the accessor methods simply return the instance variables. What is printed?", "choices": ["\"Gold true\"", "\"null true\"", "\"null false\"", "\"Gold false\""], "answer": 3, "explanation": "The line level = memberLevel correctly assigns the parameter to the instance variable, so level becomes \"Gold\". However, isActive = active assigns the instance variable's own current value (the default false) to the parameter isActive, which does nothing to the instance variable, so active remains false."},
  {"id": "3.4-intermediate-05", "course": "csa", "topic": "3.4", "tier": "intermediate", "lo": "3.4.A.2", "prompt": "public class Coupon\n{\n    private String code;\n    private double discountPercent;\n    public Coupon(String couponCode)\n    {\n        code = couponCode;\n        discountPercent = 0.0;\n    }\n    public Coupon(String couponCode, double percent)\n    {\n        code = couponCode;\n        discountPercent = percent;\n    }\n}\nWhich of the following correctly creates a Coupon object with code \"SAVE10\" and a 10.0 percent discount?", "choices": ["Coupon c = new Coupon(\"SAVE10\", 10.0);", "Coupon c = new Coupon(10.0, \"SAVE10\");", "Coupon c = new Coupon(\"SAVE10\");", "Coupon c = new Coupon(\"SAVE10\", \"10.0\");"], "answer": 0, "explanation": "The two-argument constructor expects a String followed by a double, in that order, which matches choice A exactly. Choice B reverses the argument order, choice C only sets the code (leaving the discount at its default 0.0), and choice D passes a String instead of a double for the discount."},
  {"id": "3.4-intermediate-06", "course": "csa", "topic": "3.4", "tier": "intermediate", "lo": "3.4.A.2", "prompt": "public class Score\n{\n    private int home;\n    private int away;\n    public Score(int homeScore, int awayScore)\n    {\n        home = awayScore;\n        away = homeScore;\n    }\n}\nScore s = new Score(7, 3);\nWhat are the values of home and away after this code executes?", "choices": ["home is 7, away is 3", "home is 3, away is 7", "home is 0, away is 0", "The code does not compile"], "answer": 1, "explanation": "The constructor body swaps the assignments: home is assigned the value of awayScore (3) and away is assigned the value of homeScore (7). Since homeScore is 7 and awayScore is 3, home ends up 3 and away ends up 7."},
  {"id": "3.4-intermediate-07", "course": "csa", "topic": "3.4", "tier": "intermediate", "lo": "3.4.A.2", "prompt": "A class Employee has instance variables private String name and private int id. Which constructor correctly initializes an Employee object so that name and id match the constructor's parameter values, and can be called from outside the class?", "choices": ["public Employee(String name, int id)\n{\n    int id = id;\n    String name = name;\n}", "public Employee(String empName, int empId)\n{\n    empId = id;\n    name = empName;\n}", "public Employee(String empName, int empId)\n{\n    name = empName;\n    id = empId;\n}", "private Employee(String empName, int empId)\n{\n    name = empName;\n    id = empId;\n}"], "answer": 2, "explanation": "Choice C uses distinct parameter names and correctly assigns each parameter to its corresponding instance variable. Choice A illegally redeclares local variables with the same names as the parameters and does not compile. Choice B correctly sets name but assigns empId = id, which assigns the field's default value to the parameter instead of the reverse, leaving id unset. Choice D declares the constructor private, which prevents it from being called to create an object from outside the class."},
  {"id": "3.4-intermediate-08", "course": "csa", "topic": "3.4", "tier": "intermediate", "lo": "3.4.A.5", "prompt": "public class Vehicle\n{\n    private String make;\n    private int year;\n    private boolean electric;\n    public Vehicle(String vehicleMake, int vehicleYear)\n    {\n        make = vehicleMake;\n        year = vehicleYear;\n    }\n}\nVehicle v = new Vehicle(\"Volt\", 2023);\nWhat is the value of the electric instance variable after this code executes?", "choices": ["true", "It causes a compile-time error, since electric is never assigned", "It causes a NullPointerException at runtime", "false, because instance variables not assigned in a constructor still receive their default value"], "answer": 3, "explanation": "Java initializes every instance variable to its type's default value before a constructor body runs, so any field the constructor does not explicitly assign, like electric here, simply keeps that default. For a boolean, the default is false, and it is entirely legal for a constructor to leave some fields at their default values."},
  {"id": "3.4-intermediate-09", "course": "csa", "topic": "3.4", "tier": "intermediate", "lo": "3.4.A.2", "prompt": "A class Payment defines two constructors: public Payment(int cents) and public Payment(double dollars). Which of the following calls to create a Payment object compiles and unambiguously matches exactly one of the constructors?", "choices": ["Payment p = new Payment(500);", "Payment p = new Payment(500, 0.0);", "Payment p = new Payment(\"500\");", "Payment p = new Payment();"], "answer": 0, "explanation": "The literal 500 is an int, so it matches the Payment(int cents) constructor directly without any ambiguity. There is no two-argument, String-argument, or no-argument constructor defined, so the other choices fail to compile."},
  {"id": "3.4-intermediate-10", "course": "csa", "topic": "3.4", "tier": "intermediate", "lo": "3.4.A.2", "prompt": "public class Temperature\n{\n    private double fahrenheit;\n    public Temperature(double celsius)\n    {\n        fahrenheit = celsius * 9 / 5 + 32;\n    }\n}\nTemperature t = new Temperature(20.0);\nWhat value is stored in fahrenheit after this code executes?", "choices": ["20.0", "32.0", "68.0", "36.0"], "answer": 2, "explanation": "Substituting 20.0 into the expression gives 20.0 * 9 / 5 + 32, which evaluates to 180.0 / 5 + 32, or 36.0 + 32, giving 68.0. Choice B, 32.0, only reflects the added constant and omits the scaled celsius term."},
  {"id": "3.4-intermediate-11", "course": "csa", "topic": "3.4", "tier": "intermediate", "lo": "3.4.A.2", "prompt": "public class TempRange\n{\n    private int freezingPoint;\n    private int currentTemp;\n    private int boilingPoint;\n    public TempRange(int freezing, int current, int boiling)\n    {\n        freezingPoint = freezing;\n        currentTemp = current;\n        boilingPoint = boiling;\n    }\n}\nWhich of the following object creations passes arguments that satisfy the sensible precondition freezingPoint < currentTemp < boilingPoint?", "choices": ["TempRange t = new TempRange(212, 98, 32);", "TempRange t = new TempRange(32, 250, 212);", "TempRange t = new TempRange(0, -10, 100);", "TempRange t = new TempRange(32, 98, 212);"], "answer": 3, "explanation": "Choice D passes 32, 98, and 212 for freezingPoint, currentTemp, and boilingPoint respectively, and 32 < 98 < 212 holds true. In choice A the order is reversed entirely, in choice B the current temperature exceeds the boiling point, and in choice C the current temperature is less than the freezing point."},
  {"id": "3.4-intermediate-12", "course": "csa", "topic": "3.4", "tier": "intermediate", "lo": "3.4.A.2", "prompt": "public class Author\n{\n    private String penName;\n    /* missing constructor */\n}\nElsewhere in the program, the following line is used to create an object.\nAuthor a = new Author(\"Twain\");\nWhich of the following can replace /* missing constructor */ so that the object a is correctly created?", "choices": ["public Author(String name)\n{\n    penName = name;\n}", "private Author(String name)\n{\n    penName = name;\n}", "public Author()\n{\n    penName = \"Twain\";\n}", "public Author(String penName)\n{\n    String name = penName;\n}"], "answer": 0, "explanation": "Choice A defines a public one-parameter constructor that assigns the parameter to penName, matching the call new Author(\"Twain\") and correctly setting the instance variable. Choice B uses private, which prevents the constructor from being called outside the class. Choice C has no parameters and cannot accept the argument \"Twain\" from the call. Choice D never assigns penName at all, since it only creates and assigns a local variable named name."},
  {"id": "3.4-intermediate-13", "course": "csa", "topic": "3.4", "tier": "intermediate", "lo": "3.4.A.2", "prompt": "public class BankAccount\n{\n    private String owner;\n    private double balance;\n    public BankAccount(String accountOwner, double startingBalance)\n    {\n        owner = accountOwner;\n        double balance = startingBalance;\n    }\n}\nBankAccount acct = new BankAccount(\"Jae\", 500.0);\nWhat is the value of the balance instance variable after this code executes?", "choices": ["500.0", "0.0", "It causes a compile-time error", "null"], "answer": 1, "explanation": "The statement double balance = startingBalance; declares a brand-new local variable named balance inside the constructor, which shadows the instance variable of the same name but does not affect it. The instance variable balance is therefore never assigned and keeps its default value of 0.0."},
  {"id": "3.4-intermediate-14", "course": "csa", "topic": "3.4", "tier": "intermediate", "lo": "3.4.A.2", "prompt": "A class Playlist has instance variables private String name and private int songCount. A programmer wants the following declaration to compile and correctly set both instance variables.\nPlaylist p = new Playlist(\"Road Trip\", 12);\nWhich constructor accomplishes this?", "choices": ["public Playlist(String name, int songCount)\n{\n}", "public Playlist(int songCount, String name)\n{\n    name = name;\n    songCount = songCount;\n}", "public Playlist(String playlistName, int trackCount)\n{\n    name = playlistName;\n    songCount = trackCount;\n}", "public Playlist(String playlistName, int trackCount)\n{\n    name = trackCount;\n    songCount = playlistName;\n}"], "answer": 2, "explanation": "Choice C uses distinct parameter names matched correctly to each instance variable, so it compiles for the call and sets both fields as intended. Choice A compiles but has an empty body, so both fields keep their default values instead of being set. Choice B has parameters in the wrong order for the call site, causing a type mismatch. Choice D assigns an int parameter to the String field and vice versa, which does not compile."},
  {"id": "3.4-intermediate-15", "course": "csa", "topic": "3.4", "tier": "intermediate", "lo": "3.4.A.4", "prompt": "A class Ticket defines only one constructor: public Ticket(String eventName). Which of the following statements is true?", "choices": ["Ticket t = new Ticket(); will still compile, because Java always provides a no-argument constructor.", "Ticket t = new Ticket(); will compile, and eventName will be set to \"\" by default.", "Both new Ticket() and new Ticket(\"Concert\") will compile, since one constructor is always overloaded automatically.", "Ticket t = new Ticket(); will not compile, because writing any constructor removes the automatically supplied no-argument constructor."], "answer": 3, "explanation": "Java only supplies a default no-argument constructor when a class defines no constructors at all. Once a class defines any constructor, such as the one-parameter Ticket constructor here, the automatic no-argument constructor is no longer provided, so calling new Ticket() with no arguments fails to compile."},
  {"id": "3.4-complex-01", "course": "csa", "topic": "3.4", "tier": "complex", "lo": "3.4.A.3", "prompt": "public class Point2D\n{\n    private int x;\n    private int y;\n    public Point2D(int startX, int startY)\n    {\n        x = startX;\n        y = startY;\n    }\n    public int getX()\n    {\n        return x;\n    }\n    public int getY()\n    {\n        return y;\n    }\n    public void setX(int newX)\n    {\n        x = newX;\n    }\n    public void setY(int newY)\n    {\n        y = newY;\n    }\n}\npublic class Marker\n{\n    private Point2D location;\n    public Marker(Point2D loc)\n    {\n        location = loc;\n    }\n    public int getLocationX()\n    {\n        return location.getX();\n    }\n}\nPoint2D p = new Point2D(3, 4);\nMarker m = new Marker(p);\np.setX(99);\nSystem.out.println(m.getLocationX());\nWhat value is printed, and why?", "choices": ["3, because the constructor stored a copy of p, so changes to p do not affect m", "99, because the constructor stored the same reference as p, so changing p also changes the object referenced by m's location field", "3, because Point2D objects cannot be changed once created", "99, because Marker's constructor recreates location every time getLocationX is called"], "answer": 1, "explanation": "The Marker constructor assigns location = loc directly, storing a reference to the same Point2D object that p refers to, rather than making a copy. Because location and p refer to the same object, calling p.setX(99) changes that shared object's x value, so m.getLocationX() also returns 99. Point2D is not immutable here since it provides a setX mutator."},
  {"id": "3.4-complex-02", "course": "csa", "topic": "3.4", "tier": "complex", "lo": "3.4.A.3", "prompt": "A class Interval has a private Point2D instance variable named start. A programmer wants the constructor to store an independent copy of the Point2D argument p, not a reference to the original object. Consider the following candidate constructor bodies.\nI. start = p;\nII. start = new Point2D(p.getX(), p.getY());\nIII. start = new Point2D();\nIV. start = p.getX();\nWhich candidate correctly accomplishes this?", "choices": ["I only", "III only", "IV only", "II only"], "answer": 3, "explanation": "Candidate II builds a brand-new Point2D object using the current x and y values read from p, so start becomes an independent object holding the same coordinates. Candidate I stores a direct reference to p, allowing later changes to p to affect start. Candidate III ignores p's actual coordinates entirely. Candidate IV attempts to assign an int to a Point2D field, which does not compile."},
  {"id": "3.4-complex-03", "course": "csa", "topic": "3.4", "tier": "complex", "lo": "3.4.A.2", "prompt": "public class Odometer\n{\n    private int miles;\n    private boolean reset;\n    public Odometer(int startMiles)\n    {\n        miles = startMiles;\n        reset = false;\n    }\n    public void addMiles(int extra)\n    {\n        miles = miles + extra;\n    }\n    public int getMiles()\n    {\n        return miles;\n    }\n}\nOdometer o = new Odometer(100);\no.addMiles(50);\no.addMiles(25);\nSystem.out.println(o.getMiles());\nWhat value is printed?", "choices": ["175", "150", "100", "75"], "answer": 0, "explanation": "The constructor sets miles to 100. The first addMiles(50) call increases miles to 150, and the second addMiles(25) call increases it further to 175. Choice C reflects only the constructor's initial value, ignoring both method calls."},
  {"id": "3.4-complex-04", "course": "csa", "topic": "3.4", "tier": "complex", "lo": "3.4.A.3", "prompt": "public class SafeBox\n{\n    private Point2D corner;\n    public SafeBox(Point2D p)\n    {\n        corner = new Point2D(p.getX(), p.getY());\n    }\n    public int getCornerX()\n    {\n        return corner.getX();\n    }\n}\nPoint2D p = new Point2D(5, 5);\nSafeBox box = new SafeBox(p);\np.setX(50);\nSystem.out.println(box.getCornerX());\nWhat value is printed?", "choices": ["50", "0", "5", "It causes a compile-time error"], "answer": 2, "explanation": "Because the SafeBox constructor builds a brand-new Point2D using the values read from p at construction time, corner refers to an independent object rather than p itself. Changing p afterward with p.setX(50) has no effect on that independent copy, so box.getCornerX() still returns 5."},
  {"id": "3.4-complex-05", "course": "csa", "topic": "3.4", "tier": "complex", "lo": "3.4.A.2", "prompt": "A class Inventory has instance variables private String itemName and private int stock. Consider the following four candidate constructors, each intended for a call like new Inventory(\"Widget\", 10).\nI.\npublic Inventory(String itemName, int stock)\n{\n    itemName = itemName;\n    stock = stock;\n}\nII.\npublic Inventory(String name, int quantity)\n{\n    itemName = name;\n    stock = quantity;\n}\nIII.\npublic Inventory(String name, int quantity)\n{\n    String itemName = name;\n    int stock = quantity;\n}\nIV.\npublic Inventory(int quantity, String name)\n{\n    itemName = name;\n    stock = quantity;\n}\nWhich of these constructors correctly sets the instance variables itemName and stock to the argument values, for the call new Inventory(\"Widget\", 10)?", "choices": ["I and IV only", "II only", "II and IV only", "I, II, and III"], "answer": 1, "explanation": "Only candidate II uses distinct parameter names correctly matched to each instance variable, so it correctly sets itemName and stock for this call. Candidate I reuses the instance variable names as parameter names, so each assignment only assigns a parameter to itself, leaving the fields at their defaults. Candidate III declares new local variables that shadow the instance variables, which are never actually assigned. Candidate IV's parameter order, (int, String), does not match the call's argument types, (String, int), so it fails to compile for this specific call."},
  {"id": "3.4-complex-06", "course": "csa", "topic": "3.4", "tier": "complex", "lo": "3.4.A.3", "prompt": "Using the Point2D and Marker classes defined earlier (where Marker's constructor stores location = loc directly, without copying), consider the following code.\nPoint2D shared = new Point2D(1, 1);\nMarker m1 = new Marker(shared);\nMarker m2 = new Marker(shared);\nshared.setX(9);\nSystem.out.println(m1.getLocationX() + \" \" + m2.getLocationX());\nWhat is printed?", "choices": ["\"1 1\"", "\"1 9\"", "\"9 1\"", "\"9 9\""], "answer": 3, "explanation": "Both m1 and m2 were constructed with the same shared Point2D object, and since Marker's constructor does not make a defensive copy, both m1.location and m2.location refer to that same object as shared. Calling shared.setX(9) changes that one shared object, so both m1.getLocationX() and m2.getLocationX() return 9."},
  {"id": "3.4-complex-07", "course": "csa", "topic": "3.4", "tier": "complex", "lo": "3.4.A.3", "prompt": "A class Segment has a private Point2D instance variable named endpoint. Consider the following four candidate constructor bodies for Segment(Point2D p).\nI. endpoint = p;\nII. endpoint = new Point2D(p.getX(), p.getY());\nIII. endpoint = new Point2D(0, 0);\nIV. endpoint = p.getX();\nWhich candidate both compiles successfully and prevents later changes to the original Point2D argument from affecting the Segment object's state, while still initializing endpoint to the same x and y values as p at the time of construction?", "choices": ["II", "I", "III", "IV"], "answer": 0, "explanation": "Candidate II builds a new, independent Point2D initialized with p's current coordinates, so it both matches p's initial values and is immune to later changes made through p. Candidate I stores a reference to p itself, so it is vulnerable to later aliasing. Candidate III compiles and is immune to later changes, but it always uses (0, 0) rather than matching p's actual coordinates. Candidate IV tries to assign an int to a Point2D field, which does not compile."},
  {"id": "3.4-complex-08", "course": "csa", "topic": "3.4", "tier": "complex", "lo": "3.4.A.2", "prompt": "public class SavingsAccount\n{\n    private double balance;\n    public SavingsAccount(double initialDeposit)\n    {\n        balance = initialDeposit;\n    }\n    public void applyInterest(double rate)\n    {\n        balance = balance + balance * rate;\n    }\n    public double getBalance()\n    {\n        return balance;\n    }\n}\nSavingsAccount acct = new SavingsAccount(100.0);\nacct.applyInterest(0.10);\nacct.applyInterest(0.10);\nSystem.out.println(acct.getBalance());\nWhat value is printed?", "choices": ["120.0", "100.0", "121.0", "110.0"], "answer": 2, "explanation": "The constructor sets balance to 100.0. The first applyInterest(0.10) call updates balance to 100.0 + 100.0 * 0.10, or 110.0. The second call updates balance to 110.0 + 110.0 * 0.10, or 121.0. Choice A, 120.0, incorrectly treats the interest as a flat 10.0 added twice rather than compounding."},
  {"id": "3.4-complex-09", "course": "csa", "topic": "3.4", "tier": "complex", "lo": "3.4.A.3", "prompt": "public class Region\n{\n    private Point2D center;\n    private int radius;\n    public Region(Point2D centerPoint, int r)\n    {\n        center = new Point2D(centerPoint.getX(), centerPoint.getY());\n        radius = r;\n    }\n    public int getCenterX()\n    {\n        return center.getX();\n    }\n    public int getRadius()\n    {\n        return radius;\n    }\n}\nPoint2D pt = new Point2D(2, 2);\nRegion reg = new Region(pt, 5);\npt.setX(100);\nSystem.out.println(reg.getCenterX() + \" \" + reg.getRadius());\nWhat is printed?", "choices": ["\"100 5\"", "\"2 5\"", "\"0 5\"", "\"2 0\""], "answer": 1, "explanation": "The Region constructor builds a new, independent Point2D from pt's coordinates at the time of construction, so center does not share a reference with pt. Changing pt afterward with pt.setX(100) has no effect on center, so getCenterX() still returns 2, and radius remains 5 as assigned."},
  {"id": "3.4-complex-10", "course": "csa", "topic": "3.4", "tier": "complex", "lo": "3.4.A.5", "prompt": "public class Light2\n{\n    private boolean isOn;\n    private int brightness;\n    public Light2(int startBrightness)\n    {\n        brightness = startBrightness;\n    }\n    public void toggle()\n    {\n        isOn = !isOn;\n    }\n    public int getBrightness()\n    {\n        return brightness;\n    }\n    public boolean isOnStatus()\n    {\n        return isOn;\n    }\n}\nLight2 lamp = new Light2(80);\nlamp.toggle();\nlamp.toggle();\nlamp.toggle();\nSystem.out.println(lamp.getBrightness() + \" \" + lamp.isOnStatus());\nWhat is printed?", "choices": ["\"80 false\"", "\"0 true\"", "\"0 false\"", "\"80 true\""], "answer": 3, "explanation": "The constructor never assigns isOn, so it starts at its default value of false, while brightness is set to 80. Each call to toggle() flips isOn: false, then true, then false, then true again after the third call, so the final state is brightness 80 and isOn true."},
  {"id": "3.4-complex-11", "course": "csa", "topic": "3.4", "tier": "complex", "lo": "3.4.A.3", "prompt": "A class Appointment has instance variables private String title and private Point2D location. Consider the following five candidate constructors, each intended to be called as new Appointment(\"Checkup\", somePoint).\nI.\npublic Appointment(String t, Point2D loc)\n{\n    title = t;\n    location = loc;\n}\nII.\npublic Appointment(String t, Point2D loc)\n{\n    title = t;\n    location = new Point2D(loc.getX(), loc.getY());\n}\nIII.\npublic Appointment(Point2D loc, String t)\n{\n    title = t;\n    location = new Point2D(loc.getX(), loc.getY());\n}\nIV.\npublic Appointment(String t, Point2D loc)\n{\n    title = loc.getX() + \"\";\n    location = new Point2D(0, 0);\n}\nV.\npublic Appointment(String t, Point2D loc)\n{\n    String title = t;\n    Point2D location = new Point2D(loc.getX(), loc.getY());\n}\nWhich constructor both compiles for the call new Appointment(\"Checkup\", somePoint) and correctly defends against later mutation of the original Point2D argument, while still initializing location to the same x and y values as the argument at the time of construction?", "choices": ["II only", "I and II", "III only", "II and V"], "answer": 0, "explanation": "Candidate II has the correct parameter order for the call, assigns title directly, and builds an independent copy of the Point2D argument, correctly defending against later mutation. Candidate I stores a direct reference to loc, so it is vulnerable to aliasing. Candidate III has its parameters in the wrong order for this call, (Point2D, String) instead of (String, Point2D), so it fails to compile for this call. Candidate IV compiles and is immune to later mutation of loc, but it always sets location to (0, 0) rather than loc's actual coordinates, so it fails the requirement to match the argument's x and y values at construction time. Candidate V compiles but only declares local variables that shadow the instance variables, so title and location are never actually assigned."},
  {"id": "3.4-complex-12", "course": "csa", "topic": "3.4", "tier": "complex", "lo": "3.4.A.2", "prompt": "public class Counter2\n{\n    private int value;\n    public Counter2(int startValue)\n    {\n        value = startValue * 2;\n    }\n    public void increment()\n    {\n        value++;\n    }\n    public int getValue()\n    {\n        return value;\n    }\n}\nCounter2 a = new Counter2(3);\nCounter2 b = new Counter2(a.getValue());\na.increment();\nb.increment();\nb.increment();\nSystem.out.println(a.getValue() + \" \" + b.getValue());\nWhat is printed?", "choices": ["\"7 12\"", "\"6 14\"", "\"7 14\"", "\"8 14\""], "answer": 2, "explanation": "Object a is constructed with startValue 3, so a.value becomes 3 * 2 = 6. Object b is then constructed using a.getValue(), which is 6 at that moment, so b.value becomes 6 * 2 = 12. Calling a.increment() once makes a.value 7. Calling b.increment() twice makes b.value 12, then 13, then 14, giving the final result \"7 14\"."},
  {"id": "3.4-complex-13", "course": "csa", "topic": "3.4", "tier": "complex", "lo": "3.4.A.3", "prompt": "public class Marker2\n{\n    private Point2D location;\n    public Marker2(Point2D p)\n    {\n        location = new Point2D(p.getX(), p.getY());\n    }\n    public void setLocationX(int newX)\n    {\n        location.setX(newX);\n    }\n    public int getLocationX()\n    {\n        return location.getX();\n    }\n}\nPoint2D p = new Point2D(5, 5);\nMarker2 m = new Marker2(p);\nm.setLocationX(20);\nSystem.out.println(p.getX() + \" \" + m.getLocationX());\nWhat is printed?", "choices": ["\"20 20\"", "\"5 20\"", "\"20 5\"", "\"5 5\""], "answer": 1, "explanation": "Marker2's constructor makes an independent copy of p, so location and p refer to different objects from the start. Calling m.setLocationX(20) modifies only the copy stored inside m, leaving the original object referenced by p unchanged, so p.getX() still returns 5 while m.getLocationX() returns 20."},
  {"id": "3.4-complex-14", "course": "csa", "topic": "3.4", "tier": "complex", "lo": "3.4.A.2", "prompt": "A class Distance defines two constructors: public Distance(int meters) and public Distance(double kilometers). Which of the following statements is true about the call Distance d = new Distance(5);?", "choices": ["It is ambiguous and fails to compile, since 5 could match either constructor equally well.", "It calls the Distance(double kilometers) constructor, since int values are always widened to double first.", "It fails to compile because neither constructor accepts an int literal.", "It calls the Distance(int meters) constructor, since an exact int match is preferred over widening to double."], "answer": 3, "explanation": "Java prefers an exact type match over an implicit widening conversion when resolving overloaded methods and constructors, so the int literal 5 matches Distance(int meters) directly without needing to widen to double. Widening to double would only be considered if no exact int match existed."},
  {"id": "3.4-complex-15", "course": "csa", "topic": "3.4", "tier": "complex", "lo": "3.4.A.3", "prompt": "Using the original Marker class (whose constructor stores location = loc directly, without copying), consider the following code.\nPoint2D p1 = new Point2D(1, 1);\nMarker m = new Marker(p1);\np1 = new Point2D(9, 9);\nSystem.out.println(m.getLocationX());\nWhat is printed?", "choices": ["9, because m.location and p1 always refer to the same object", "It causes a compile-time error", "0, because reassigning p1 resets location to its default value", "1, because m.location still references the original Point2D object, unaffected by p1 being reassigned to a new object"], "answer": 3, "explanation": "When Marker was constructed, its location field was set to reference the same object that p1 pointed to at that time, the Point2D holding (1, 1). Later reassigning the variable p1 to a brand-new Point2D object only changes what p1 refers to; it does not alter or affect the original object, so m.location still refers to that original (1, 1) object and getLocationX() returns 1."},
];
